"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[683],{8683:s=>{s.exports=JSON.parse('{"key":"db","title":"数据库","desc":"","glyph":"库","cls":"b-db","modules":[{"name":"课程内容","chapters":[{"n":1,"slug":"1","title":"PostgreSQL安装","group":"课程内容","kicker_mod":"数据库","sec_meta":[{"name":"安装 Docker","anchor":"安装-Docker"},{"name":"安装 PostgreSQL","anchor":"安装-PostgreSQL"},{"name":"安装管理工具 pgAdmin","anchor":"安装管理工具-pgAdmin"},{"name":"作业","anchor":"作业"}],"html":"<h1 id=\\"PostgreSQL安装\\">PostgreSQL安装</h1>\\n<p><a href=\\"https://www.postgresql.org/\\">PostgreSQL官网</a></p>\\n<table>\\n<thead>\\n<tr>\\n<th>特性</th>\\n<th>PostgreSQL</th>\\n<th>MySQL</th>\\n<th>Oracle</th>\\n<th>SQL Server</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>开发机构</strong></td>\\n<td>社区</td>\\n<td>Oracle Corporation</td>\\n<td>Oracle Corporation</td>\\n<td>Microsoft</td>\\n</tr>\\n<tr>\\n<td><strong>协议/许可</strong></td>\\n<td>PostgreSQL License（开源免费）</td>\\n<td>GPL / 商用双许可</td>\\n<td>商用收费</td>\\n<td>商用收费</td>\\n</tr>\\n<tr>\\n<td><strong>费用</strong></td>\\n<td>完全免费</td>\\n<td>社区版免费，企业版付费</td>\\n<td>高额许可费</td>\\n<td>按核心/用户授权收费</td>\\n</tr>\\n<tr>\\n<td><strong>ACID 合规</strong></td>\\n<td>原生完整支持</td>\\n<td>取决于存储引擎（InnoDB 支持）</td>\\n<td>完整支持</td>\\n<td>完整支持</td>\\n</tr>\\n<tr>\\n<td><strong>SQL 标准兼容性</strong></td>\\n<td>高度兼容，最贴近标准 SQL</td>\\n<td>部分兼容，方言较多</td>\\n<td>高度兼容</td>\\n<td>高度兼容</td>\\n</tr>\\n<tr>\\n<td><strong>数据类型</strong></td>\\n<td>丰富（数组、JSON、JSONB、UUID、自定义类型等）</td>\\n<td>基础类型丰富，JSON 支持较晚</td>\\n<td>丰富</td>\\n<td>丰富</td>\\n</tr>\\n<tr>\\n<td><strong>扩展性</strong></td>\\n<td>支持扩展（Extension），生态丰富（PostGIS、TimescaleDB 等）</td>\\n<td>插件较少，主要靠存储引擎</td>\\n<td>功能内置，扩展复杂</td>\\n<td>功能内置，扩展复杂</td>\\n</tr>\\n<tr>\\n<td><strong>并发控制</strong></td>\\n<td>MVCC（多版本并发控制）</td>\\n<td>MVCC（InnoDB）</td>\\n<td>MVCC</td>\\n<td>MVCC（快照隔离）</td>\\n</tr>\\n<tr>\\n<td><strong>复制</strong></td>\\n<td>流复制、逻辑复制，成熟稳定</td>\\n<td>主从复制、组复制</td>\\n<td>Data Guard、GoldenGate</td>\\n<td>Always On、镜像复制</td>\\n</tr>\\n<tr>\\n<td><strong>全文搜索</strong></td>\\n<td>内置全文搜索（tsvector/tsquery）</td>\\n<td>内置全文索引</td>\\n<td>Oracle Text</td>\\n<td>内置全文搜索</td>\\n</tr>\\n<tr>\\n<td><strong>NoSQL 能力</strong></td>\\n<td>JSONB 支持，可作文档数据库</td>\\n<td>JSON 支持，MongoDB 兼容（8.0+）</td>\\n<td>JSON、XML 支持</td>\\n<td>JSON 支持</td>\\n</tr>\\n<tr>\\n<td><strong>GIS spatial</strong></td>\\n<td>PostGIS（业界最强开源 GIS 扩展）</td>\\n<td>基础 Spatial 扩展</td>\\n<td>Oracle Spatial</td>\\n<td>SQL Server Spatial</td>\\n</tr>\\n<tr>\\n<td><strong>平台支持</strong></td>\\n<td>Linux、macOS、Windows、BSD</td>\\n<td>Linux、macOS、Windows</td>\\n<td>Linux、Windows</td>\\n<td>仅 Windows（2017 起支持 Linux）</td>\\n</tr>\\n<tr>\\n<td><strong>存储引擎</strong></td>\\n<td>仅一种（不区分引擎）</td>\\n<td>多种引擎（InnoDB、MyISAM 等）</td>\\n<td>内置一种</td>\\n<td>内置一种</td>\\n</tr>\\n<tr>\\n<td><strong>分区表</strong></td>\\n<td>支持声明式分区</td>\\n<td>支持分区</td>\\n<td>支持分区</td>\\n<td>支持分区</td>\\n</tr>\\n<tr>\\n<td><strong>性能优化</strong></td>\\n<td>查询规划器强大，适合复杂查询</td>\\n<td>简单查询快，复杂查询弱于 PG</td>\\n<td>优化器成熟，适合大型企业</td>\\n<td>优化器成熟，与微软生态集成好</td>\\n</tr>\\n<tr>\\n<td><strong>社区与生态</strong></td>\\n<td>活跃开源社区</td>\\n<td>最大用户群体</td>\\n<td>企业级支持完善</td>\\n<td>企业级支持完善</td>\\n</tr>\\n<tr>\\n<td><strong>典型场景</strong></td>\\n<td>地理信息、数据分析、Web 应用</td>\\n<td>Web 应用（搭配 LAMP/LEMP）</td>\\n<td>大型企业核心系统</td>\\n<td>微软生态企业应用</td>\\n</tr>\\n</tbody>\\n</table>\\n<h2 id=\\"安装-Docker\\">安装 Docker</h2>\\n<h3 id=\\"安装-Docker-Desktop\\">安装 Docker Desktop</h3>\\n<p>访问 <a href=\\"https://www.docker.com/products/docker-desktop\\">https://www.docker.com/products/docker-desktop</a> 下载 Docker Desktop</p>\\n<p>⚠️注意：windows电脑均下载AMD版本的，不要下载ARM版本的，课堂上说的有误！</p>\\n<h3 id=\\"配置镜像加速器\\">配置镜像加速器</h3>\\n<p>由于网络原因，国内用户拉取 Docker 镜像可能很慢，需要配置镜像加速器。</p>\\n<p><strong>打开 Docker Desktop → Settings → Docker Engine</strong>，在配置文件中添加 <code>registry-mirrors</code>：</p>\\n<div class=\\"codehilite lang-json\\"><pre><span></span><code><span class=\\"p\\">{</span>\\n<span class=\\"w\\">  </span><span class=\\"nt\\">\\"registry-mirrors\\"</span><span class=\\"p\\">:</span><span class=\\"w\\"> </span><span class=\\"p\\">[</span>\\n<span class=\\"w\\">    </span><span class=\\"s2\\">\\"https://docker.m.daocloud.io\\"</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"s2\\">\\"https://docker.1ms.run\\"</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"s2\\">\\"https://docker.aityp.com\\"</span>\\n<span class=\\"w\\">  </span><span class=\\"p\\">]</span>\\n<span class=\\"p\\">}</span>\\n</code></pre></div>\\n\\n<p>点击 <strong>Apply &amp; Restart</strong> 使配置生效。</p>\\n<h3 id=\\"验证-Docker-安装\\">验证 Docker 安装</h3>\\n<p>打开终端（Terminal），执行：</p>\\n<div class=\\"codehilite lang-bash\\"><pre><span></span><code>docker<span class=\\"w\\"> </span>--version\\n</code></pre></div>\\n\\n<p>预期输出（版本号可能不同）：</p>\\n<div class=\\"codehilite\\"><pre><span></span><code>Docker version 29.2.0, build 0b9d198\\n</code></pre></div>\\n\\n<p>验证 Docker 正常运行：</p>\\n<div class=\\"codehilite lang-bash\\"><pre><span></span><code>docker<span class=\\"w\\"> </span>info\\n</code></pre></div>\\n\\n<p>能看到 Server 相关信息表示安装成功。</p>\\n<hr />\\n<h2 id=\\"安装-PostgreSQL\\">安装 PostgreSQL</h2>\\n<h3 id=\\"拉取-PostgreSQL-镜像\\">拉取 PostgreSQL 镜像</h3>\\n<div class=\\"codehilite lang-bash\\"><pre><span></span><code>docker<span class=\\"w\\"> </span>pull<span class=\\"w\\"> </span>postgres:16\\n</code></pre></div>\\n\\n<blockquote>\\n<p>我们选择 PostgreSQL 16，这是目前最新的稳定版本。</p>\\n</blockquote>\\n<h3 id=\\"创建并运行-PostgreSQL-容器\\">创建并运行 PostgreSQL 容器</h3>\\n<div class=\\"codehilite lang-bash\\"><pre><span></span><code>docker<span class=\\"w\\"> </span>run<span class=\\"w\\"> </span>-d<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>--name<span class=\\"w\\"> </span>pg16<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-e<span class=\\"w\\"> </span><span class=\\"nv\\">POSTGRES_USER</span><span class=\\"o\\">=</span>admin<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-e<span class=\\"w\\"> </span><span class=\\"nv\\">POSTGRES_PASSWORD</span><span class=\\"o\\">=</span><span class=\\"m\\">123123</span><span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-p<span class=\\"w\\"> </span><span class=\\"m\\">5432</span>:5432<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-v<span class=\\"w\\"> </span><span class=\\"s2\\">\\"你的本地路径:/var/lib/postgresql/data\\"</span><span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>postgres:16\\n</code></pre></div>\\n\\n<p>参数说明：</p>\\n<table>\\n<thead>\\n<tr>\\n<th>参数</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>-d</code></td>\\n<td>后台运行容器</td>\\n</tr>\\n<tr>\\n<td><code>--name pg16</code></td>\\n<td>容器命名为 pg16</td>\\n</tr>\\n<tr>\\n<td><code>-e POSTGRES_USER=admin</code></td>\\n<td>设置超级用户名为 admin</td>\\n</tr>\\n<tr>\\n<td><code>-e POSTGRES_PASSWORD=admin123</code></td>\\n<td>设置密码为 admin123</td>\\n</tr>\\n<tr>\\n<td><code>-p 5432:5432</code></td>\\n<td>将宿主机 5432 端口映射到容器 5432 端口</td>\\n</tr>\\n<tr>\\n<td><code>-v ...:/var/lib/postgresql/data</code></td>\\n<td>数据持久化卷，容器删除后数据不丢失</td>\\n</tr>\\n</tbody>\\n</table>\\n<h3 id=\\"验证-PostgreSQL-容器\\">验证 PostgreSQL 容器</h3>\\n<p>进入容器连接 PostgreSQL</p>\\n<div class=\\"codehilite lang-bash\\"><pre><span></span><code>docker<span class=\\"w\\"> </span><span class=\\"nb\\">exec</span><span class=\\"w\\"> </span>-it<span class=\\"w\\"> </span>pg16<span class=\\"w\\"> </span>psql<span class=\\"w\\"> </span>-U<span class=\\"w\\"> </span>admin<span class=\\"w\\"> </span>-d<span class=\\"w\\"> </span>admin\\n</code></pre></div>\\n\\n<p>参数说明：</p>\\n<table>\\n<thead>\\n<tr>\\n<th>参数</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>docker exec -it pg16</code></td>\\n<td>在 pg16 容器中执行交互式命令</td>\\n</tr>\\n<tr>\\n<td><code>psql -U admin -d demo_db</code></td>\\n<td>使用用户 admin 连接 demo_db 数据库</td>\\n</tr>\\n</tbody>\\n</table>\\n<p>连接成功后，在 <code>demo_db=#</code> 提示符下执行以下命令验证：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 查看当前连接信息</span>\\n<span class=\\"err\\">\\\\</span><span class=\\"n\\">conninfo</span>\\n\\n<span class=\\"c1\\">-- 列出所有数据库</span>\\n<span class=\\"err\\">\\\\</span><span class=\\"n\\">l</span>\\n\\n<span class=\\"c1\\">-- 查看当前用户</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">current_user</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 退出psql</span>\\n<span class=\\"err\\">\\\\</span><span class=\\"n\\">q</span>\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"安装管理工具-pgAdmin\\">安装管理工具 pgAdmin</h2>\\n<p>官网地址：https://www.pgadmin.org/</p>\\n<p>同样使用 Docker 安装：</p>\\n<div class=\\"codehilite lang-bash\\"><pre><span></span><code>docker<span class=\\"w\\"> </span>run<span class=\\"w\\"> </span>-d<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>--name<span class=\\"w\\"> </span>pgadmin4<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-e<span class=\\"w\\"> </span><span class=\\"nv\\">PGADMIN_DEFAULT_EMAIL</span><span class=\\"o\\">=</span>admin@qq.com<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-e<span class=\\"w\\"> </span><span class=\\"nv\\">PGADMIN_DEFAULT_PASSWORD</span><span class=\\"o\\">=</span><span class=\\"m\\">123123</span><span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>-p<span class=\\"w\\"> </span><span class=\\"m\\">5050</span>:80<span class=\\"w\\"> </span><span class=\\"se\\">\\\\</span>\\n<span class=\\"w\\">  </span>dpage/pgadmin4\\n</code></pre></div>\\n\\n<p>参数说明：</p>\\n<table>\\n<thead>\\n<tr>\\n<th>参数</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>-e PGADMIN_DEFAULT_EMAIL</code></td>\\n<td>登录邮箱</td>\\n</tr>\\n<tr>\\n<td><code>-e PGADMIN_DEFAULT_PASSWORD</code></td>\\n<td>登录密码</td>\\n</tr>\\n<tr>\\n<td><code>-p 5050:80</code></td>\\n<td>宿主机 5050 端口映射到容器 80 端口</td>\\n</tr>\\n<tr>\\n<td><code>--link pg16:pg16</code></td>\\n<td>连接到 pg16 容器，网络互通</td>\\n</tr>\\n</tbody>\\n</table>\\n<p>接下来可以打开浏览器访问 http://localhost:5050</p>\\n<hr />\\n<h2 id=\\"作业\\">作业</h2>\\n<p>完成数据库环境搭建</p>","search_secs":[{"name":"安装 Docker","body":"安装 Docker Desktop 访问 https://www.docker.com/products/docker-desktop 下载 Docker Desktop ⚠️注意：windows电脑均下载AMD版本的，不要下载ARM版本的，课堂上说的有误！ 配置镜像加速器 由于网络原因，国内用户拉取 Docker 镜像可能很慢，需要配置镜像加速器。 打开 Docker Desktop → Settings → Docker Engine，在配置文件中添加 registry-mirrors： 点击 Apply & Restart 使配置生效。 验证 Docker 安装 打开终端（Terminal），执行： 预期输出（版本号可能不同）： 验证 Docker 正常运行： 能看到 Server 相关信息表示安装成功。 ---"},{"name":"安装 PostgreSQL","body":"拉取 PostgreSQL 镜像 我们选择 PostgreSQL 16，这是目前最新的稳定版本。 创建并运行 PostgreSQL 容器 参数说明： 验证 PostgreSQL 容器 进入容器连接 PostgreSQL 参数说明： 连接成功后，在 demo_db=# 提示符下执行以下命令验证： ---"},{"name":"安装管理工具 pgAdmin","body":"官网地址：https://www.pgadmin.org/ 同样使用 Docker 安装： 参数说明： 接下来可以打开浏览器访问 http://localhost:5050 ---"},{"name":"作业","body":"完成数据库环境搭建"}],"progress_key":"db-1"},{"n":2,"slug":"2","title":"DDL","group":"课程内容","kicker_mod":"数据库","sec_meta":[{"name":"数据库核心概念","anchor":"数据库核心概念"},{"name":"什么是SQL","anchor":"什么是SQL"},{"name":"SQL的细分","anchor":"SQL的细分"},{"name":"DDL语言","anchor":"DDL语言"},{"name":"小结","anchor":"小结"},{"name":"作业","anchor":"作业"}],"html":"<h1 id=\\"DDL\\">DDL</h1>\\n<h2 id=\\"数据库核心概念\\">数据库核心概念</h2>\\n<p><img loading=\\"lazy\\" alt=\\"image-20260608133054687\\" src=\\"https://resource.duyiedu.com/yuanjin/202606081330833.png\\" /></p>\\n<h2 id=\\"什么是SQL\\">什么是SQL</h2>\\n<p>SQL（Structured Query Language，结构化查询语言）是操作关系型数据库的标准语言。无论使用 PostgreSQL、MySQL 还是 Oracle，SQL 的语法都高度通用。</p>\\n<p>SQL 主要做两件事：</p>\\n<ol>\\n<li><strong>告诉数据库做什么</strong>（而非怎么做）—— SQL 是声明式语言</li>\\n<li><strong>操作数据</strong>—— 增、删、改、查</li>\\n</ol>\\n<hr />\\n<h2 id=\\"SQL的细分\\">SQL的细分</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>分类</th>\\n<th>全称</th>\\n<th>作用</th>\\n<th>常见关键字</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>DDL</strong></td>\\n<td>Data Definition Language</td>\\n<td><strong>数据定义</strong>，操作数据库和表结构</td>\\n<td><code>CREATE</code>、<code>ALTER</code>、<code>DROP</code>、<code>TRUNCATE</code></td>\\n</tr>\\n<tr>\\n<td><strong>DML</strong></td>\\n<td>Data Manipulation Language</td>\\n<td><strong>数据操作</strong>，对表数据进行增删改查</td>\\n<td><code>INSERT</code>、<code>SELECT</code>、<code>UPDATE</code>、<code>DELETE</code></td>\\n</tr>\\n<tr>\\n<td><strong>DCL</strong></td>\\n<td>Data Control Language</td>\\n<td><strong>数据控制</strong>，管理用户和权限</td>\\n<td><code>GRANT</code>、<code>REVOKE</code></td>\\n</tr>\\n<tr>\\n<td><strong>TCL</strong></td>\\n<td>Transaction Control Language</td>\\n<td><strong>事务控制</strong>，管理事务</td>\\n<td><code>BEGIN</code>、<code>COMMIT</code>、<code>ROLLBACK</code>、<code>SAVEPOINT</code></td>\\n</tr>\\n</tbody>\\n</table>\\n<blockquote>\\n<p>要操作数据，先得有存放数据的结构。所以学习顺序是 <strong>DDL → DML</strong>，先建表，再操作数据。</p>\\n</blockquote>\\n<hr />\\n<h2 id=\\"DDL语言\\">DDL语言</h2>\\n<p>DDL 操作的是<strong>结构</strong>而非数据，包括：数据库的创建删除、表的创建修改删除等。</p>\\n<h3 id=\\"数据库操作\\">数据库操作</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 创建数据库</span>\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">DATABASE</span><span class=\\"w\\"> </span><span class=\\"n\\">demo</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 删除数据库</span>\\n<span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">DATABASE</span><span class=\\"w\\"> </span><span class=\\"n\\">demo</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"CREATE-创建表\\">CREATE — 创建表</h3>\\n<p><strong>基本语法：</strong></p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"err\\">表名</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"err\\">列名</span><span class=\\"w\\"> </span><span class=\\"err\\">数据类型</span><span class=\\"w\\"> </span><span class=\\"p\\">[</span><span class=\\"err\\">约束</span><span class=\\"p\\">],</span>\\n<span class=\\"w\\">    </span><span class=\\"err\\">列名</span><span class=\\"w\\"> </span><span class=\\"err\\">数据类型</span><span class=\\"w\\"> </span><span class=\\"p\\">[</span><span class=\\"err\\">约束</span><span class=\\"p\\">],</span>\\n<span class=\\"w\\">    </span><span class=\\"p\\">...</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<p><strong>示例：</strong></p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"nb\\">INTEGER</span><span class=\\"w\\"> </span><span class=\\"k\\">CHECK</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"p\\">),</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"nb\\">NUMERIC</span><span class=\\"p\\">(</span><span class=\\"mi\\">5</span><span class=\\"p\\">,</span><span class=\\"mi\\">2</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">DEFAULT</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"p\\">.</span><span class=\\"mi\\">00</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">email</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">100</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">UNIQUE</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">created_at</span><span class=\\"w\\"> </span><span class=\\"k\\">TIMESTAMP</span><span class=\\"w\\"> </span><span class=\\"k\\">DEFAULT</span><span class=\\"w\\"> </span><span class=\\"k\\">CURRENT_TIMESTAMP</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h4 id=\\"常见数据类型\\">常见数据类型</h4>\\n<table>\\n<thead>\\n<tr>\\n<th>类型</th>\\n<th>说明</th>\\n<th>示例</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>INTEGER</code> / <code>INT</code></td>\\n<td>整数（4字节）</td>\\n<td><code>age INT</code></td>\\n</tr>\\n<tr>\\n<td><code>BIGINT</code></td>\\n<td>大整数（8字节）</td>\\n<td><code>views BIGINT</code></td>\\n</tr>\\n<tr>\\n<td><code>SMALLINT</code></td>\\n<td>小整数（2字节）</td>\\n<td><code>quantity SMALLINT</code></td>\\n</tr>\\n<tr>\\n<td><code>SERIAL</code></td>\\n<td>自增整数（相当于 <code>INTEGER</code> + 自动序列）</td>\\n<td><code>id SERIAL</code></td>\\n</tr>\\n<tr>\\n<td><code>BIGSERIAL</code></td>\\n<td>自增大整数</td>\\n<td><code>id BIGSERIAL</code></td>\\n</tr>\\n<tr>\\n<td><code>NUMERIC(m, n)</code></td>\\n<td>定点数，m总位数，n小数位，<strong>精确存储</strong></td>\\n<td><code>price NUMERIC(10,2)</code></td>\\n</tr>\\n<tr>\\n<td><code>REAL</code></td>\\n<td>浮点数（4字节），不精确</td>\\n<td><code>rate REAL</code></td>\\n</tr>\\n<tr>\\n<td><code>DOUBLE PRECISION</code></td>\\n<td>双精度浮点数（8字节）</td>\\n<td><code>score DOUBLE PRECISION</code></td>\\n</tr>\\n<tr>\\n<td><code>VARCHAR(n)</code></td>\\n<td>变长字符串，最大n字符</td>\\n<td><code>name VARCHAR(50)</code></td>\\n</tr>\\n<tr>\\n<td><code>CHAR(n)</code></td>\\n<td>定长字符串，不足补空格</td>\\n<td><code>code CHAR(3)</code></td>\\n</tr>\\n<tr>\\n<td><code>TEXT</code></td>\\n<td>不限长度字符串</td>\\n<td><code>description TEXT</code></td>\\n</tr>\\n<tr>\\n<td><code>BOOLEAN</code></td>\\n<td>布尔值，true/false</td>\\n<td><code>is_active BOOLEAN</code></td>\\n</tr>\\n<tr>\\n<td><code>DATE</code></td>\\n<td>日期（年月日）</td>\\n<td><code>birth DATE</code></td>\\n</tr>\\n<tr>\\n<td><code>TIMESTAMP</code></td>\\n<td>日期+时间，不带时区</td>\\n<td><code>created_at TIMESTAMP</code></td>\\n</tr>\\n<tr>\\n<td><code>TIMESTAMPTZ</code></td>\\n<td>日期+时间，<strong>带时区</strong></td>\\n<td><code>updated_at TIMESTAMPTZ</code></td>\\n</tr>\\n<tr>\\n<td><code>TIME</code></td>\\n<td>时间（时分秒）</td>\\n<td><code>start_time TIME</code></td>\\n</tr>\\n<tr>\\n<td><code>JSON</code></td>\\n<td>JSON 数据（文本存储）</td>\\n<td><code>meta JSON</code></td>\\n</tr>\\n<tr>\\n<td><code>JSONB</code></td>\\n<td><strong>二进制</strong> JSON，支持索引和高效查询</td>\\n<td><code>data JSONB</code></td>\\n</tr>\\n<tr>\\n<td><code>UUID</code></td>\\n<td>通用唯一标识符</td>\\n<td><code>id UUID DEFAULT gen_random_uuid()</code></td>\\n</tr>\\n</tbody>\\n</table>\\n<hr />\\n<h4 id=\\"常见约束\\">常见约束</h4>\\n<table>\\n<thead>\\n<tr>\\n<th>约束</th>\\n<th>作用</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>PRIMARY KEY</code></td>\\n<td>主键，唯一标识一行，自带 NOT NULL + UNIQUE</td>\\n</tr>\\n<tr>\\n<td><code>NOT NULL</code></td>\\n<td>不允许为空</td>\\n</tr>\\n<tr>\\n<td><code>UNIQUE</code></td>\\n<td>值必须唯一</td>\\n</tr>\\n<tr>\\n<td><code>DEFAULT 值</code></td>\\n<td>不传值时使用的默认值</td>\\n</tr>\\n<tr>\\n<td><code>CHECK (条件)</code></td>\\n<td>检查约束，值必须满足条件</td>\\n</tr>\\n</tbody>\\n</table>\\n<h4 id=\\"主键\\">主键</h4>\\n<p>主键（Primary Key）是表中<strong>唯一标识每一行数据</strong>的列或列组合。它具有两个核心特性：</p>\\n<ol>\\n<li><strong>唯一性</strong>：主键的值在表中不能重复</li>\\n<li><strong>非空</strong>：主键的值不能为 NULL</li>\\n</ol>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 单列主键</span>\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"p\\">...</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 复合主键（多列联合唯一标识一行）</span>\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">student_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INT</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">course_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INT</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">enrolled_at</span><span class=\\"w\\"> </span><span class=\\"k\\">TIMESTAMP</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">student_id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">course_id</span><span class=\\"p\\">)</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"ALTER-修改表结构\\">ALTER — 修改表结构</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 添加列</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ADD</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">phone</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">20</span><span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 删除列</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">phone</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 修改列的数据类型（现有数据可隐式转换时直接用）</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">TYPE</span><span class=\\"w\\"> </span><span class=\\"nb\\">NUMERIC</span><span class=\\"p\\">(</span><span class=\\"mi\\">6</span><span class=\\"p\\">,</span><span class=\\"mi\\">2</span><span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 无法隐式转换时，用 USING 指定转换规则</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">TYPE</span><span class=\\"w\\"> </span><span class=\\"nb\\">INTEGER</span><span class=\\"w\\"> </span><span class=\\"k\\">USING</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">::</span><span class=\\"nb\\">INTEGER</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 设置默认值</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"k\\">DEFAULT</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"p\\">.</span><span class=\\"mi\\">00</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 移除默认值</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">DEFAULT</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 添加 NOT NULL 约束</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 添加 CHECK 约束</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ADD</span><span class=\\"w\\"> </span><span class=\\"k\\">CONSTRAINT</span><span class=\\"w\\"> </span><span class=\\"n\\">score_check</span><span class=\\"w\\"> </span><span class=\\"k\\">CHECK</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"w\\"> </span><span class=\\"k\\">AND</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&lt;=</span><span class=\\"w\\"> </span><span class=\\"mi\\">100</span><span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 重命名列</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">RENAME</span><span class=\\"w\\"> </span><span class=\\"k\\">COLUMN</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">TO</span><span class=\\"w\\"> </span><span class=\\"n\\">total_score</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 重命名表</span>\\n<span class=\\"k\\">ALTER</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">RENAME</span><span class=\\"w\\"> </span><span class=\\"k\\">TO</span><span class=\\"w\\"> </span><span class=\\"n\\">pupils</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><strong>思考：</strong> 修改列的数据类型时，如果已有数据，数据库会尝试做隐式转换。转换失败会报错。</p>\\n</blockquote>\\n<hr />\\n<h3 id=\\"DROP-删除表\\">DROP — 删除表</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 删除表（连带数据一起删除）</span>\\n<span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 如果表存在才删除，避免报错</span>\\n<span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"k\\">IF</span><span class=\\"w\\"> </span><span class=\\"k\\">EXISTS</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 级联删除（连依赖该表的对象一并删除）</span>\\n<span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">CASCADE</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"TRUNCATE-清空表\\">TRUNCATE — 清空表</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 清空表数据，但保留表结构</span>\\n<span class=\\"k\\">TRUNCATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 清空所有关联表的数据</span>\\n<span class=\\"k\\">TRUNCATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">orders</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><strong>DELETE vs TRUNCATE vs DROP：</strong></p>\\n</blockquote>\\n<table>\\n<thead>\\n<tr>\\n<th>操作</th>\\n<th>类型</th>\\n<th>是否可回滚</th>\\n<th>速度</th>\\n<th>是否保留结构</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>DELETE FROM</code></td>\\n<td>DML</td>\\n<td>是</td>\\n<td>慢（逐行删除，可带 WHERE）</td>\\n<td>保留</td>\\n</tr>\\n<tr>\\n<td><code>TRUNCATE</code></td>\\n<td>DDL</td>\\n<td>是（PostgreSQL 中支持事务回滚）</td>\\n<td>快（直接重置存储）</td>\\n<td>保留</td>\\n</tr>\\n<tr>\\n<td><code>DROP</code></td>\\n<td>DDL</td>\\n<td>否</td>\\n<td>最快</td>\\n<td>不保留</td>\\n</tr>\\n</tbody>\\n</table>\\n<hr />\\n<h2 id=\\"小结\\">小结</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>操作</th>\\n<th>关键字</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>创建数据库</td>\\n<td><code>CREATE DATABASE</code></td>\\n<td>新建一个数据库</td>\\n</tr>\\n<tr>\\n<td>删除数据库</td>\\n<td><code>DROP DATABASE</code></td>\\n<td>删除整个数据库，数据全丢</td>\\n</tr>\\n<tr>\\n<td>创建表</td>\\n<td><code>CREATE TABLE</code></td>\\n<td>定义表结构、列和约束</td>\\n</tr>\\n<tr>\\n<td>修改表</td>\\n<td><code>ALTER TABLE</code></td>\\n<td>增删列、改类型、改约束</td>\\n</tr>\\n<tr>\\n<td>删除表</td>\\n<td><code>DROP TABLE</code></td>\\n<td>删除表和数据</td>\\n</tr>\\n<tr>\\n<td>清空表</td>\\n<td><code>TRUNCATE TABLE</code></td>\\n<td>清空数据，保留表结构</td>\\n</tr>\\n</tbody>\\n</table>\\n<hr />\\n<h2 id=\\"作业\\">作业</h2>\\n<p>让AI帮你生成SQL语句，完成下面的功能</p>\\n<blockquote>\\n<p>建议提示词：</p>\\n<p>接下来我需要做一些数据库的操作，数据库的类型是PostgreSQL，版本是16。请你根据我的要求生成相应的SQL语句，我会将你的语句复制下来，到数据库中去执行。如果你准备好了，就请回复准备好了。</p>\\n</blockquote>\\n<ol>\\n<li>创建一个 <code>courses_db</code> 数据库</li>\\n<li>创建 <code>students</code> 表，包含姓名、年龄、性别</li>\\n<li>创建 <code>courses</code> 表，包含课程名称、课程描述、授课老师</li>\\n<li>请进入docker容器pg16，导出<code>courses_db</code>数据库为<code>SQL</code>，只需要干干净净的建表语句即可，我会直接复制语句到<code>pgadmin</code>中执行</li>\\n<li>【人工】请删除并重建干净的数据库，并使用导出的<code>SQL</code>恢复</li>\\n</ol>","search_secs":[{"name":"数据库核心概念","body":""},{"name":"什么是SQL","body":"SQL（Structured Query Language，结构化查询语言）是操作关系型数据库的标准语言。无论使用 PostgreSQL、MySQL 还是 Oracle，SQL 的语法都高度通用。 SQL 主要做两件事： 1. 告诉数据库做什么（而非怎么做）—— SQL 是声明式语言 2. 操作数据—— 增、删、改、查 ---"},{"name":"SQL的细分","body":"要操作数据，先得有存放数据的结构。所以学习顺序是 DDL → DML，先建表，再操作数据。 ---"},{"name":"DDL语言","body":"DDL 操作的是结构而非数据，包括：数据库的创建删除、表的创建修改删除等。 数据库操作 --- CREATE — 创建表 基本语法： 示例： --- 常见数据类型 --- 常见约束 主键 主键（Primary Key）是表中唯一标识每一行数据的列或列组合。它具有两个核心特性： 1. 唯一性：主键的值在表中不能重复 2. 非空：主键的值不能为 NULL --- ALTER — 修改表结构 思考： 修改列的数据类型时，如果已有数据，数据库会尝试做隐式转换。转换失败会报错。 --- DROP — 删除表 --- TRUNCATE — 清空表 DELETE vs TRUNCATE vs DROP： ---"},{"name":"小结","body":"---"},{"name":"作业","body":"让AI帮你生成SQL语句，完成下面的功能 建议提示词： 接下来我需要做一些数据库的操作，数据库的类型是PostgreSQL，版本是16。请你根据我的要求生成相应的SQL语句，我会将你的语句复制下来，到数据库中去执行。如果你准备好了，就请回复准备好了。 1. 创建一个 courses_db 数据库 2. 创建 students 表，包含姓名、年龄、性别 3. 创建 courses 表，包含课程名称、课程描述、授课老师 4. 请进入docker容器pg16，导出courses_db数据库为SQL，只需要干干净净的建表语句即可，我会直接复制语句到pgadmin中执行 5. 【人工】请删除并重建干净的数据库，并使用导出的SQL恢复"}],"progress_key":"db-2"},{"n":3,"slug":"3","title":"表间关系","group":"课程内容","kicker_mod":"数据库","sec_meta":[{"name":"为什么需要表间关系？","anchor":"为什么需要表间关系"},{"name":"三种常见关系","anchor":"三种常见关系"},{"name":"外键（Foreign Key）详解","anchor":"外键Foreign-Key详解"},{"name":"ERD","anchor":"ERD"},{"name":"练习题","anchor":"练习题"}],"html":"<h1 id=\\"表间关系\\">表间关系</h1>\\n<h2 id=\\"为什么需要表间关系\\">为什么需要表间关系？</h2>\\n<p>在关系型数据库中，为了<strong>减少数据冗余</strong>、<strong>保证数据一致性</strong>，我们会将数据拆分到多个表中。但拆开之后，如何把这些表重新关联起来？这就需要在表之间建立<strong>关系</strong>。</p>\\n<hr />\\n<h2 id=\\"三种常见关系\\">三种常见关系</h2>\\n<h3 id=\\"一对一11\\">一对一（1:1）</h3>\\n<p><strong>定义</strong>：A 和 B 可以描述为，一个 A 对应一个 B；一个 B 对应一个 A</p>\\n<p>常见的一对一关系：</p>\\n<ul>\\n<li>用户和用户信息（详情）</li>\\n<li>员工和工位</li>\\n<li>订单与支付详情</li>\\n<li>...</li>\\n</ul>\\n<blockquote>\\n<p>数据库中，一对一关系理论上可以合并为一张表，只是为了性能考虑而拆分</p>\\n<p>哪些情况考虑拆分：</p>\\n<ul>\\n<li>访问频率差异明显</li>\\n<li>单行数据量过大</li>\\n<li>访问权限差异</li>\\n</ul>\\n</blockquote>\\n<p><strong>实现方式</strong>：</p>\\n<ul>\\n<li>在任意一表中添加<strong>外键</strong>指向另一表的主键</li>\\n<li>为这个外键加上 <strong>UNIQUE</strong> 约束，保证一对一</li>\\n</ul>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">users</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">username</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">user_profiles</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">user_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INTEGER</span><span class=\\"w\\"> </span><span class=\\"k\\">UNIQUE</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span><span class=\\"w\\">      </span><span class=\\"c1\\">-- UNIQUE 保证一对一</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">bio</span><span class=\\"w\\"> </span><span class=\\"nb\\">TEXT</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">FOREIGN</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">user_id</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">REFERENCES</span><span class=\\"w\\"> </span><span class=\\"n\\">users</span><span class=\\"p\\">(</span><span class=\\"n\\">id</span><span class=\\"p\\">)</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"一对多1N-最常见\\">一对多（1:N）⭐ 最常见</h3>\\n<p><strong>定义</strong>：一个 A 可以有多个 B；一个 B 只能对应一个 A</p>\\n<p>常见的一对多关系：</p>\\n<ul>\\n<li>部门（departments）↔ 员工（employees）</li>\\n<li>分类（categories）↔ 商品（products）</li>\\n<li>用户（users）↔ 订单（orders）</li>\\n</ul>\\n<p><strong>实现方式</strong>：</p>\\n<ul>\\n<li>在 <strong>多</strong> 的一方添加外键，指向 <strong>一</strong> 的一方的主键</li>\\n<li>外键不能加 UNIQUE</li>\\n</ul>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">departments</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">employees</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">dept_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INTEGER</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">FOREIGN</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">dept_id</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">REFERENCES</span><span class=\\"w\\"> </span><span class=\\"n\\">departments</span><span class=\\"p\\">(</span><span class=\\"n\\">id</span><span class=\\"p\\">)</span>\\n<span class=\\"w\\">    </span><span class=\\"c1\\">-- 多个员工可以属于同一个部门，所以 dept_id 不需要 UNIQUE</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"多对多MN\\">多对多（M:N）</h3>\\n<p><strong>定义</strong>：一个 A 对应多个 B；一个 B 对应多个 A</p>\\n<p>常见的多对多关系：</p>\\n<ul>\\n<li>学生（students）↔ 课程（courses）</li>\\n<li>订单（orders）↔ 商品（products）</li>\\n<li>演员（actors）↔ 电影（movies）</li>\\n</ul>\\n<p><strong>实现方式</strong>：</p>\\n<ul>\\n<li>多对多<strong>不能直接实现</strong>，必须引入一张<strong>中间表（关联表）</strong></li>\\n<li>中间表包含两个外键，分别指向两张表的主键</li>\\n<li>这两个外键组成<strong>联合主键</strong></li>\\n<li>中间表除了两个外键，还可以存放关系本身的附加属性（如 <code>enroll_date</code> 等）</li>\\n</ul>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">title</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">100</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 中间表：记录学生和课程的选课关系</span>\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">student_courses</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">student_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INTEGER</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">course_id</span><span class=\\"w\\">  </span><span class=\\"nb\\">INTEGER</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">enroll_date</span><span class=\\"w\\"> </span><span class=\\"nb\\">DATE</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">student_id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">course_id</span><span class=\\"p\\">),</span><span class=\\"w\\">          </span><span class=\\"c1\\">-- 联合主键</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">FOREIGN</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">student_id</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">REFERENCES</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">(</span><span class=\\"n\\">id</span><span class=\\"p\\">),</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">FOREIGN</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">course_id</span><span class=\\"p\\">)</span><span class=\\"w\\">  </span><span class=\\"k\\">REFERENCES</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"p\\">(</span><span class=\\"n\\">id</span><span class=\\"p\\">)</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"外键Foreign-Key详解\\">外键（Foreign Key）详解</h2>\\n<h3 id=\\"什么是外键\\">什么是外键？</h3>\\n<p><strong>外键（Foreign Key，简称 FK）</strong> 是一个字段（或一组字段），它<strong>指向另一张表的主键</strong>，用来建立和加强两个表之间的连接。</p>\\n<table>\\n<thead>\\n<tr>\\n<th>术语</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>主表（父表）</strong></td>\\n<td>被引用的表</td>\\n</tr>\\n<tr>\\n<td><strong>从表（子表）</strong></td>\\n<td>包含外键的表</td>\\n</tr>\\n</tbody>\\n</table>\\n<h3 id=\\"外键的约束行为\\">外键的约束行为</h3>\\n<p>创建外键时可以指定当<strong>父表数据被删除或更新</strong>时，子表如何处理：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">FOREIGN</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">dept_id</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">REFERENCES</span><span class=\\"w\\"> </span><span class=\\"n\\">departments</span><span class=\\"p\\">(</span><span class=\\"n\\">id</span><span class=\\"p\\">)</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"k\\">DELETE</span><span class=\\"w\\"> </span><span class=\\"k\\">CASCADE</span><span class=\\"w\\">    </span><span class=\\"c1\\">-- 级联删除：部门删除时，所属员工也删除</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"k\\">CASCADE</span><span class=\\"p\\">;</span><span class=\\"w\\">   </span><span class=\\"c1\\">-- 级联更新：部门id更新时，员工dept_id自动更新</span>\\n</code></pre></div>\\n\\n<table>\\n<thead>\\n<tr>\\n<th>选项</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>NO ACTION</code>（PostgreSQL 默认）</td>\\n<td>如果存在关联记录，禁止删除/更新父表，支持延迟检查（DEFERRABLE）</td>\\n</tr>\\n<tr>\\n<td><code>RESTRICT</code></td>\\n<td>同 NO ACTION，但<strong>不支持</strong>延迟检查</td>\\n</tr>\\n<tr>\\n<td><code>CASCADE</code></td>\\n<td>级联操作：父表变更，子表自动跟随</td>\\n</tr>\\n<tr>\\n<td><code>SET NULL</code></td>\\n<td>父表删除/更新后，子表外键设为 NULL</td>\\n</tr>\\n</tbody>\\n</table>\\n<blockquote>\\n<p>延迟检查和事务有关联，现在无法解释，你可以暂时认为<code>NO ACTION</code>和<code>RESTRICT</code>是等同的</p>\\n</blockquote>\\n<h3 id=\\"外键的优缺点\\">外键的优缺点</h3>\\n<table>\\n<thead>\\n<tr>\\n<th>优点</th>\\n<th>缺点</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>保证数据完整性，防止脏数据</td>\\n<td>降低写入性能（每次插入/更新需要检查）</td>\\n</tr>\\n<tr>\\n<td>关系清晰，语义明确</td>\\n<td>在分库分表、分布式场景下难以使用</td>\\n</tr>\\n<tr>\\n<td>数据库层面自动约束</td>\\n<td>某些场景下级联操作难以追踪</td>\\n</tr>\\n</tbody>\\n</table>\\n<blockquote>\\n<p>⚠️ <strong>实际开发中的权衡</strong>：大型互联网项目中，有些团队会<strong>放弃数据库外键</strong>，在<strong>应用层（代码中）保证数据完整性</strong>，以获得更高性能。但在传统企业应用、ERP、财务系统中，外键仍是标准做法。</p>\\n</blockquote>\\n<hr />\\n<h2 id=\\"ERD\\">ERD</h2>\\n<p><strong>ERD（Entity-Relationship Diagram，实体关系图）</strong> 是一种用于描述数据库中实体（表）及其之间关系的图形化工具。在 ERD 中，矩形代表实体（表），连线代表关系，并标注了关系的类型（1:1、1:N、M:N）。</p>\\n<p>下图是电商数据库的 ER 图，涵盖了三种表间关系：</p>\\n<div class=\\"codehilite lang-mermaid\\"><pre><span></span><code>erDiagram\\n    user {\\n        int id PK\\n        varchar username UK\\n        varchar email UK\\n    }\\n    user_profile {\\n        int id PK\\n        int user_id FK,UK\\n        varchar full_name\\n        text bio\\n    }\\n    category {\\n        int id PK\\n        varchar name\\n    }\\n    product {\\n        int id PK\\n        int category_id FK\\n        varchar name\\n    }\\n    sku {\\n        int id PK\\n        int product_id FK\\n        varchar sku_code UK\\n        decimal price\\n        int stock\\n    }\\n    order {\\n        int id PK\\n        int user_id FK\\n        varchar order_no UK\\n        varchar status\\n        decimal total_amount\\n    }\\n    order_items {\\n        int order_id PK,FK\\n        int sku_id PK,FK\\n        int quantity\\n        decimal price\\n    }\\n\\n    user ||--|| user_profile : \\"一对一\\"\\n    category ||--o{ product : \\"一对多\\"\\n    product ||--o{ sku : \\"一对多\\"\\n    user ||--o{ order : \\"一对多\\"\\n    order ||--o{ order_items : \\"\\"\\n    sku ||--o{ order_items : \\"\\"\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"练习题\\">练习题</h2>\\n<h3 id=\\"阅读SQL\\">阅读SQL</h3>\\n<ol>\\n<li>阅读《电商数据库设计.sql》，确保自己能理解每一行SQL的含义</li>\\n<li>在<code>pgadmin</code>中新建数据库<code>product_db</code>，并在其中运行SQL，完成建表</li>\\n<li>使用<code>pgadmin</code>查看它的ERD</li>\\n</ol>\\n<h3 id=\\"表关系判断\\">表关系判断</h3>\\n<p>根据以下场景，分析需要设计哪些表，并说明表之间的关系（1:1、1:N、M:N）。</p>\\n<p><strong>场景一：学校选课系统</strong></p>\\n<p>一个学校有多个院系，每个院系有多个学生和多个老师。学生可以选修多门课程，一门课程可以被多个学生选修，选修后会记录成绩。每个老师只能属于一个院系，可以教授多门课程。</p>\\n<p><strong>场景二：社交媒体平台</strong></p>\\n<p>用户可以发布多条动态，每条动态可以有多个评论。用户可以关注其他用户（关注者与被关注者）。每条动态可以有多个标签，一个标签也可以出现在多条动态中。</p>\\n<p><strong>场景三：医院挂号系统</strong></p>\\n<p>一个医院有多个科室，每个科室有多名医生和多名护士。每个患者可以多次挂号，一次挂号只对应一个医生。一次挂号会产生一条就诊记录，一条就诊记录对应一份病历。</p>\\n<p><strong>场景四：在线视频平台</strong></p>\\n<p>用户可以上传多个视频，每个视频属于一个分类。用户可以收藏多个视频，一个视频可以被多个用户收藏。每个视频可以有多个弹幕，每条弹幕由某个用户发送。</p>\\n<hr />\\n<h3 id=\\"找茬题\\">找茬题</h3>\\n<p>以下是一个<strong>会员制超市收银系统</strong>的 ER 图，其中<strong>隐藏了一处错误的关系</strong>。请找出这个错误，并说明应该怎么修正。</p>\\n<p><strong>场景描述</strong>：会员每次购物会产生一张小票，小票上记录本次购物的多个商品及数量。每个商品属于一个分类。一个供应商可以供应多个商品，但每个商品只由一个供应商供应。</p>\\n<div class=\\"codehilite lang-mermaid\\"><pre><span></span><code>erDiagram\\n    会员 {\\n        int id PK\\n        varchar 姓名\\n        varchar 电话\\n    }\\n    小票 {\\n        int id PK\\n        int 会员_id FK\\n        decimal 总金额\\n        timestamp 创建时间\\n    }\\n    小票明细 {\\n        int 小票_id PK,FK\\n        int 商品_id PK,FK\\n        int 数量\\n        decimal 单价\\n    }\\n    商品 {\\n        int id PK\\n        int 分类_id FK\\n        int 供应商_id FK\\n        varchar 名称\\n        decimal 价格\\n    }\\n    分类 {\\n        int id PK\\n        varchar 名称\\n    }\\n    供应商 {\\n        int id PK\\n        varchar 名称\\n        varchar 联系人\\n    }\\n\\n    会员 ||--o{ 小票 : \\"购物\\"\\n    小票 ||--o{ 小票明细 : \\"包含\\"\\n    商品 ||--|| 小票明细 : \\"\\"\\n    分类 ||--o{ 商品 : \\"分类\\"\\n    供应商 ||--o{ 商品 : \\"供应\\"\\n</code></pre></div>","search_secs":[{"name":"为什么需要表间关系？","body":"在关系型数据库中，为了减少数据冗余、保证数据一致性，我们会将数据拆分到多个表中。但拆开之后，如何把这些表重新关联起来？这就需要在表之间建立关系。 ---"},{"name":"三种常见关系","body":"一对一（1:1） 定义：A 和 B 可以描述为，一个 A 对应一个 B；一个 B 对应一个 A 常见的一对一关系： 用户和用户信息（详情） 员工和工位 订单与支付详情 ... 数据库中，一对一关系理论上可以合并为一张表，只是为了性能考虑而拆分 哪些情况考虑拆分： - 访问频率差异明显 - 单行数据量过大 - 访问权限差异 实现方式： 在任意一表中添加外键指向另一表的主键 为这个外键加上 UNIQUE 约束，保证一对一 --- 一对多（1:N）⭐ 最常见 定义：一个 A 可以有多个 B；一个 B 只能对应一个 A 常见的一对多关系： 部门（departments）↔ 员工（employees） 分类（categories）↔ 商品（products） 用户（users）↔ 订单（orders） 实现方式： 在 多 的一方添加外键，指向 一 的一方的主键 外键不能加 UNIQUE --- 多对"},{"name":"外键（Foreign Key）详解","body":"什么是外键？ 外键（Foreign Key，简称 FK） 是一个字段（或一组字段），它指向另一张表的主键，用来建立和加强两个表之间的连接。 外键的约束行为 创建外键时可以指定当父表数据被删除或更新时，子表如何处理： 延迟检查和事务有关联，现在无法解释，你可以暂时认为NO ACTION和RESTRICT是等同的 外键的优缺点 ⚠️ 实际开发中的权衡：大型互联网项目中，有些团队会放弃数据库外键，在应用层（代码中）保证数据完整性，以获得更高性能。但在传统企业应用、ERP、财务系统中，外键仍是标准做法。 ---"},{"name":"ERD","body":"ERD（Entity-Relationship Diagram，实体关系图） 是一种用于描述数据库中实体（表）及其之间关系的图形化工具。在 ERD 中，矩形代表实体（表），连线代表关系，并标注了关系的类型（1:1、1:N、M:N）。 下图是电商数据库的 ER 图，涵盖了三种表间关系： ---"},{"name":"练习题","body":"阅读SQL 1. 阅读《电商数据库设计.sql》，确保自己能理解每一行SQL的含义 2. 在pgadmin中新建数据库product_db，并在其中运行SQL，完成建表 3. 使用pgadmin查看它的ERD 表关系判断 根据以下场景，分析需要设计哪些表，并说明表之间的关系（1:1、1:N、M:N）。 场景一：学校选课系统 一个学校有多个院系，每个院系有多个学生和多个老师。学生可以选修多门课程，一门课程可以被多个学生选修，选修后会记录成绩。每个老师只能属于一个院系，可以教授多门课程。 场景二：社交媒体平台 用户可以发布多条动态，每条动态可以有多个评论。用户可以关注其他用户（关注者与被关注者）。每条动态可以有多个标签，一个标签也可以出现在多条动态中。 场景三：医院挂号系统 一个医院有多个科室，每个科室有多名医生和多名护士。每个患者可以多次挂号，一次挂号只对应一个医生。一次挂号会产生一条就诊记"}],"progress_key":"db-3"},{"n":4,"slug":"4","title":"DML","group":"课程内容","kicker_mod":"数据库","sec_meta":[{"name":"INSERT — 增（插入）","anchor":"INSERT-增插入"},{"name":"DELETE — 删（删除）","anchor":"DELETE-删删除"},{"name":"UPDATE — 改（更新）","anchor":"UPDATE-改更新"},{"name":"SELECT — 查（查询）","anchor":"SELECT-查查询"},{"name":"小结","anchor":"小结"},{"name":"作业","anchor":"作业"}],"html":"<h1 id=\\"DML\\">DML</h1>\\n<p>DML（Data Manipulation Language，数据操纵语言）用于对表中的数据进行<strong>增、删、改、查</strong>。</p>\\n<blockquote>\\n<p>学习 DML 之前，请先确保已经完成 DDL 的学习，有了表和结构才能操作数据。</p>\\n</blockquote>\\n<hr />\\n<h2 id=\\"INSERT-增插入\\">INSERT — 增（插入）</h2>\\n<h3 id=\\"基本语法\\">基本语法</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"err\\">表名</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"err\\">列</span><span class=\\"mi\\">1</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"err\\">列</span><span class=\\"mi\\">2</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"p\\">...)</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"err\\">值</span><span class=\\"mi\\">1</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"err\\">值</span><span class=\\"mi\\">2</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"p\\">...);</span>\\n</code></pre></div>\\n\\n<h3 id=\\"示例\\">示例</h3>\\n<p>假设有学生表：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"nb\\">INTEGER</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"nb\\">NUMERIC</span><span class=\\"p\\">(</span><span class=\\"mi\\">5</span><span class=\\"p\\">,</span><span class=\\"mi\\">2</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">DEFAULT</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"p\\">.</span><span class=\\"mi\\">00</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">email</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">100</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">UNIQUE</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<h4 id=\\"插入完整数据\\">插入完整数据</h4>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">22</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">95</span><span class=\\"p\\">.</span><span class=\\"mi\\">5</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'zhangsan@example.com\'</span><span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<h4 id=\\"插入部分列\\">插入部分列</h4>\\n<p>省略的列会使用默认值（如果有 <code>DEFAULT</code>）或 <code>NULL</code>：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'李四\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'lisi@example.com\'</span><span class=\\"p\\">);</span>\\n<span class=\\"c1\\">-- age → NULL，score → 0.00</span>\\n</code></pre></div>\\n\\n<h4 id=\\"省略列名\\">省略列名</h4>\\n<p>如果提供全部列的值（包括自增列），可以省略列名，但<strong>不推荐</strong>，可读性差：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"k\\">DEFAULT</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'王五\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">20</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">88</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'wangwu@example.com\'</span><span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"一次插入多行\\">一次插入多行</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span>\\n<span class=\\"w\\">    </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'赵六\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">21</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">92</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'zhaoliu@example.com\'</span><span class=\\"p\\">),</span>\\n<span class=\\"w\\">    </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'孙七\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">23</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">87</span><span class=\\"p\\">.</span><span class=\\"mi\\">5</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'sunqi@example.com\'</span><span class=\\"p\\">),</span>\\n<span class=\\"w\\">    </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'周八\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">22</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">91</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'zhouba@example.com\'</span><span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"查询并插入INSERT-SELECT\\">查询并插入（INSERT ... SELECT）</h3>\\n<p>将查询结果直接插入到表中：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">backup_students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">18</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"RETURNING-返回插入的数据\\">RETURNING — 返回插入的数据</h3>\\n<p>PostgreSQL 特有的 <code>RETURNING</code> 子句，可以返回被插入行的数据：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'吴九\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">19</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">85</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'wujiu@example.com\'</span><span class=\\"p\\">)</span>\\n<span class=\\"n\\">RETURNING</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<p>只返回指定列：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'吴九\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">19</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">85</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'wujiu@example.com\'</span><span class=\\"p\\">)</span>\\n<span class=\\"n\\">RETURNING</span><span class=\\"w\\"> </span><span class=\\"n\\">id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"ON-CONFLICT-冲突处理UPSERT\\">ON CONFLICT — 冲突处理（UPSERT）</h3>\\n<p>PostgreSQL 的 <code>INSERT ... ON CONFLICT</code> 可以实现\\"存在则更新，不存在则插入\\"。</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">25</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">99</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'zhangsan@example.com\'</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">CONFLICT</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">DO</span><span class=\\"w\\"> </span><span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">EXCLUDED</span><span class=\\"p\\">.</span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">EXCLUDED</span><span class=\\"p\\">.</span><span class=\\"n\\">score</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><code>EXCLUDED</code> 指代冲突时本次要插入的新值。</p>\\n</blockquote>\\n<p>不更新，忽略冲突：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">25</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">99</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'zhangsan@example.com\'</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">CONFLICT</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">email</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">DO</span><span class=\\"w\\"> </span><span class=\\"k\\">NOTHING</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"DELETE-删删除\\">DELETE — 删（删除）</h2>\\n<h3 id=\\"基本语法_1\\">基本语法</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">DELETE</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"err\\">表名</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"err\\">条件</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><strong>⚠️ 一定不要忘记写 WHERE！</strong> 不带 WHERE 会清空表。</p>\\n</blockquote>\\n<h3 id=\\"示例_1\\">示例</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 删除指定行</span>\\n<span class=\\"k\\">DELETE</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 删除所有行（危险操作）</span>\\n<span class=\\"k\\">DELETE</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"TRUNCATE-与-DELETE-的区别\\">TRUNCATE 与 DELETE 的区别</h3>\\n<table>\\n<thead>\\n<tr>\\n<th>特性</th>\\n<th>DELETE</th>\\n<th>TRUNCATE</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>类型</td>\\n<td>DML</td>\\n<td>DDL</td>\\n</tr>\\n<tr>\\n<td>是否可带 WHERE</td>\\n<td>是</td>\\n<td>否</td>\\n</tr>\\n<tr>\\n<td>速度</td>\\n<td>慢（逐行删除）</td>\\n<td>快（重置存储）</td>\\n</tr>\\n<tr>\\n<td>可回滚</td>\\n<td>是（事务内）</td>\\n<td>是（PostgreSQL 事务内）</td>\\n</tr>\\n<tr>\\n<td>重置自增序列</td>\\n<td>否</td>\\n<td>是</td>\\n</tr>\\n<tr>\\n<td>触发 ON DELETE 触发器</td>\\n<td>是</td>\\n<td>否</td>\\n</tr>\\n</tbody>\\n</table>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- DELETE 不会重置自增序列</span>\\n<span class=\\"k\\">DELETE</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'新学生\'</span><span class=\\"p\\">);</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- id 继续递增</span>\\n\\n<span class=\\"c1\\">-- TRUNCATE 会重置自增序列</span>\\n<span class=\\"k\\">TRUNCATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'新学生\'</span><span class=\\"p\\">);</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- id 从 1 重新开始</span>\\n</code></pre></div>\\n\\n<h3 id=\\"RETURNING-返回被删除的数据\\">RETURNING — 返回被删除的数据</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">DELETE</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&lt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">60</span>\\n<span class=\\"n\\">RETURNING</span><span class=\\"w\\"> </span><span class=\\"n\\">id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"UPDATE-改更新\\">UPDATE — 改（更新）</h2>\\n<h3 id=\\"基本语法_2\\">基本语法</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"err\\">表名</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"err\\">列</span><span class=\\"mi\\">1</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"err\\">值</span><span class=\\"mi\\">1</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"err\\">列</span><span class=\\"mi\\">2</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"err\\">值</span><span class=\\"mi\\">2</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"err\\">条件</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><strong>⚠️ 一定不要忘记写 WHERE！</strong> 不带 WHERE 会更新所有行。</p>\\n</blockquote>\\n<h3 id=\\"示例_2\\">示例</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 更新单列</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">98</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 更新多列</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">23</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">96</span><span class=\\"p\\">.</span><span class=\\"mi\\">0</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'李四\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 带表达式更新</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">+</span><span class=\\"w\\"> </span><span class=\\"mi\\">5</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"o\\">&lt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">20</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 更新所有行（危险操作）</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"使用其他表的数据更新\\">使用其他表的数据更新</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span>\\n<span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">score</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">exam_scores</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">student_id</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"RETURNING-返回更新后的数据\\">RETURNING — 返回更新后的数据</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">100</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span>\\n<span class=\\"n\\">RETURNING</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"SELECT-查查询\\">SELECT — 查（查询）</h2>\\n<h3 id=\\"基本语法_3\\">基本语法</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"err\\">列</span><span class=\\"mi\\">1</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"err\\">列</span><span class=\\"mi\\">2</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"p\\">...</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"err\\">表名</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"查询所有列\\">查询所有列</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><code>*</code> 表示所有列。开发中建议明确写出列名，避免查询不必要的字段。</p>\\n</blockquote>\\n<h3 id=\\"查询指定列\\">查询指定列</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"列别名\\">列别名</h3>\\n<p>使用 <code>AS</code> 给列起别名（<code>AS</code> 可省略）：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">姓名</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"err\\">成绩</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"WHERE-条件过滤\\">WHERE — 条件过滤</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 等值查询</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 范围查询</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">90</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 多条件（AND / OR）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"mi\\">20</span><span class=\\"w\\"> </span><span class=\\"k\\">AND</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"mi\\">90</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- IN 查询</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"k\\">IN</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"mi\\">20</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">22</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">24</span><span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- BETWEEN 区间</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">BETWEEN</span><span class=\\"w\\"> </span><span class=\\"mi\\">80</span><span class=\\"w\\"> </span><span class=\\"k\\">AND</span><span class=\\"w\\"> </span><span class=\\"mi\\">95</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- LIKE 模糊匹配</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">LIKE</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张%\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- IS NULL / IS NOT NULL</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">email</span><span class=\\"w\\"> </span><span class=\\"k\\">IS</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><code>LIKE</code> 中 <code>%</code> 匹配任意多个字符，<code>_</code> 匹配单个字符。</p>\\n</blockquote>\\n<hr />\\n<h3 id=\\"ORDER-BY-排序\\">ORDER BY — 排序</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 升序（默认）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ORDER</span><span class=\\"w\\"> </span><span class=\\"k\\">BY</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 降序</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ORDER</span><span class=\\"w\\"> </span><span class=\\"k\\">BY</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">DESC</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 多列排序</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">ORDER</span><span class=\\"w\\"> </span><span class=\\"k\\">BY</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"k\\">DESC</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">ASC</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"LIMIT-和-OFFSET-分页\\">LIMIT 和 OFFSET — 分页</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 只取前 3 条</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">LIMIT</span><span class=\\"w\\"> </span><span class=\\"mi\\">3</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 跳过 2 条，取 3 条（第 3~5 条）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">LIMIT</span><span class=\\"w\\"> </span><span class=\\"mi\\">3</span><span class=\\"w\\"> </span><span class=\\"k\\">OFFSET</span><span class=\\"w\\"> </span><span class=\\"mi\\">2</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 简写：LIMIT 偏移量, 数量（MySQL 兼容写法，PostgreSQL 也支持）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">LIMIT</span><span class=\\"w\\"> </span><span class=\\"mi\\">2</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">3</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p>OFFSET 从 0 开始计数。第 1 条偏移量为 0。</p>\\n</blockquote>\\n<hr />\\n<h3 id=\\"DISTINCT-去重\\">DISTINCT — 去重</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 查询不重复的年龄</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">DISTINCT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 多列去重（组合不重复才保留）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">DISTINCT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"聚合函数\\">聚合函数</h3>\\n<table>\\n<thead>\\n<tr>\\n<th>函数</th>\\n<th>作用</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>COUNT(*)</code></td>\\n<td>统计行数</td>\\n</tr>\\n<tr>\\n<td><code>COUNT(列名)</code></td>\\n<td>统计非 NULL 行数</td>\\n</tr>\\n<tr>\\n<td><code>SUM(列名)</code></td>\\n<td>求和</td>\\n</tr>\\n<tr>\\n<td><code>AVG(列名)</code></td>\\n<td>求平均值</td>\\n</tr>\\n<tr>\\n<td><code>MAX(列名)</code></td>\\n<td>求最大值</td>\\n</tr>\\n<tr>\\n<td><code>MIN(列名)</code></td>\\n<td>求最小值</td>\\n</tr>\\n</tbody>\\n</table>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">COUNT</span><span class=\\"p\\">(</span><span class=\\"o\\">*</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">总人数</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">AVG</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">平均分</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">MAX</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">最高分</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">MIN</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">最低分</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"GROUP-BY-分组\\">GROUP BY — 分组</h3>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 按年龄分组，统计每组人数</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">COUNT</span><span class=\\"p\\">(</span><span class=\\"o\\">*</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">人数</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">GROUP</span><span class=\\"w\\"> </span><span class=\\"k\\">BY</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 按年龄分组，计算每组平均分</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">AVG</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">平均分</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">GROUP</span><span class=\\"w\\"> </span><span class=\\"k\\">BY</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p>使用 <code>GROUP BY</code> 时，<code>SELECT</code> 中出现的非聚合列必须出现在 <code>GROUP BY</code> 中。</p>\\n</blockquote>\\n<h3 id=\\"HAVING-分组后过滤\\">HAVING — 分组后过滤</h3>\\n<p><code>WHERE</code> 在分组前过滤，<code>HAVING</code> 在分组后过滤：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">AVG</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"err\\">平均分</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span>\\n<span class=\\"k\\">GROUP</span><span class=\\"w\\"> </span><span class=\\"k\\">BY</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span>\\n<span class=\\"k\\">HAVING</span><span class=\\"w\\"> </span><span class=\\"k\\">AVG</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"mi\\">90</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><strong>SQL 子句执行顺序：</strong> <code>FROM</code> → <code>WHERE</code> → <code>GROUP BY</code> → <code>HAVING</code> → <code>SELECT</code> → <code>ORDER BY</code> → <code>LIMIT</code></p>\\n</blockquote>\\n<hr />\\n<h3 id=\\"表连接JOIN\\">表连接（JOIN）</h3>\\n<p>创建示例表：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">SERIAL</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">100</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">teacher</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">student_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INT</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">course_id</span><span class=\\"w\\"> </span><span class=\\"nb\\">INT</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">enrolled_at</span><span class=\\"w\\"> </span><span class=\\"k\\">TIMESTAMP</span><span class=\\"w\\"> </span><span class=\\"k\\">DEFAULT</span><span class=\\"w\\"> </span><span class=\\"k\\">CURRENT_TIMESTAMP</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">student_id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">course_id</span><span class=\\"p\\">)</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<h4 id=\\"INNER-JOIN-内连接\\">INNER JOIN — 内连接</h4>\\n<p>只返回两表中匹配的行：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"n\\">course</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span>\\n<span class=\\"k\\">INNER</span><span class=\\"w\\"> </span><span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">student_id</span>\\n<span class=\\"k\\">INNER</span><span class=\\"w\\"> </span><span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">course_id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h4 id=\\"LEFT-JOIN-左外连接\\">LEFT JOIN — 左外连接</h4>\\n<p>返回左表所有行，右表无匹配则补 NULL：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"n\\">course</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span>\\n<span class=\\"k\\">LEFT</span><span class=\\"w\\"> </span><span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">student_id</span>\\n<span class=\\"k\\">LEFT</span><span class=\\"w\\"> </span><span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">course_id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h4 id=\\"RIGHT-JOIN-右外连接\\">RIGHT JOIN — 右外连接</h4>\\n<p>返回右表所有行，左表无匹配则补 NULL：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"n\\">course</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span>\\n<span class=\\"k\\">RIGHT</span><span class=\\"w\\"> </span><span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">student_id</span>\\n<span class=\\"k\\">RIGHT</span><span class=\\"w\\"> </span><span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">course_id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h4 id=\\"表别名\\">表别名</h4>\\n<p>使用别名简化写法：</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"n\\">course</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span>\\n<span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">student_id</span>\\n<span class=\\"k\\">JOIN</span><span class=\\"w\\"> </span><span class=\\"n\\">courses</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">course_id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"k\\">c</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h3 id=\\"子查询\\">子查询</h3>\\n<p>子查询是嵌套在另一个 SQL 中的查询，用 <code>()</code> 包裹。</p>\\n<h4 id=\\"标量子查询返回单个值\\">标量子查询（返回单个值）</h4>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">AVG</span><span class=\\"p\\">(</span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<h4 id=\\"行子查询返回单行多列\\">行子查询（返回单行多列）</h4>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<h4 id=\\"表子查询返回多行多列\\">表子查询（返回多行多列）</h4>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"k\\">IN</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">DISTINCT</span><span class=\\"w\\"> </span><span class=\\"n\\">age</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">score</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">90</span><span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<h4 id=\\"EXISTS-子查询\\">EXISTS 子查询</h4>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">students</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"k\\">EXISTS</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"mi\\">1</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">enrollments</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">e</span><span class=\\"p\\">.</span><span class=\\"n\\">student_id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">s</span><span class=\\"p\\">.</span><span class=\\"n\\">id</span>\\n<span class=\\"p\\">);</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><code>EXISTS</code> 只关心子查询是否有返回结果，不关心具体值，通常写 <code>SELECT 1</code> 即可。</p>\\n</blockquote>\\n<hr />\\n<h2 id=\\"小结\\">小结</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>操作</th>\\n<th>关键字</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>插入数据（增）</td>\\n<td><code>INSERT</code></td>\\n<td>- 插入单行<br>- 插入多行<br>- 冲突时更新或忽略（<code>ON CONFLICT</code>）</td>\\n</tr>\\n<tr>\\n<td>删除数据（删）</td>\\n<td><code>DELETE</code></td>\\n<td>- 删除指定行<br>- 删除所有行</td>\\n</tr>\\n<tr>\\n<td>更新数据（改）</td>\\n<td><code>UPDATE</code></td>\\n<td>- 更新指定行、指定列的数据<br>- 更新所有行、指定列的数据</td>\\n</tr>\\n<tr>\\n<td>查询数据（查）</td>\\n<td><code>SELECT</code></td>\\n<td>- 查询指定表、指定列的数据<br>- 可以按照条件过滤<br>- 可以排序<br>- 可以分页<br>- 可以去重（行）<br>- 可以聚合统计（求数量、和、平均、...）<br>- 可以分组聚合（求每个性别的平均年龄、求每个商品的总销售额）</td>\\n</tr>\\n</tbody>\\n</table>\\n<p>危险操作：</p>\\n<ol>\\n<li><strong>删除所有</strong> <code>DELETE FROM 表名</code></li>\\n<li><strong>更新所有</strong> <code>UPDATE</code>语句中没有<code>WHERE</code></li>\\n</ol>\\n<h2 id=\\"作业\\">作业</h2>\\n<p>使用 <code>pgAdmin 4</code> 连接 PostgreSQL 16，完成以下练习：</p>\\n<ol>\\n<li>使用<code>电商数据库设计.sql</code>建表（和上节课相同结构）</li>\\n<li>使用<code>电商数据库示例数据.sql</code>添加示例数据</li>\\n<li>查询所有商品分类的名称和描述</li>\\n<li>查询所有用户的用户名、邮箱和注册时间</li>\\n<li>查询品牌为\\"华为\\"的所有商品</li>\\n<li>查询价格低于 500 元的 SKU（商品规格）</li>\\n<li>查询库存大于 300 的 SKU</li>\\n<li>查询 2024 年注册的用户</li>\\n<li>查询状态为\\"completed\\"的已完成订单</li>\\n<li>查询所有不同的商品品牌</li>\\n<li>查询所有不同的订单状态</li>\\n<li>查询最贵的 5 个 SKU</li>\\n<li>查询最新注册的 10 个用户</li>\\n<li>统计用户总数、商品总数、SKU 总数</li>\\n<li>计算所有 SKU 的平均价格、最高价和最低价</li>\\n<li>统计每个分类下有多少个商品</li>\\n<li>统计每个品牌的商品数量，只显示商品数超过 2 的品牌</li>\\n<li>统计每个用户的订单数量</li>\\n<li>统计每个订单状态的数量（pending/paid/shipped/completed/cancelled）</li>\\n<li>查询每个商品的平均售价</li>\\n<li>查询每件商品最便宜的 SKU 价格和最贵的 SKU 价格，以及差价</li>\\n<li>查询每个分类的商品总库存价值</li>\\n<li>查询商品及其所属分类名称</li>\\n<li>查询每个用户及其个人资料信息</li>\\n<li>查询订单明细，显示订单编号、商品名称、SKU 规格、数量、单价，并进行分页，每页10条，显示第3页</li>\\n<li>查询每个用户的订单总消费金额，只显示总消费超过 10000 的用户</li>\\n<li>查询哪些商品从未被任何订单购买过</li>\\n<li>查询下单次数少于5次的用户</li>\\n<li>查询购买了\\"Dell XPS 15\\"的用户名单</li>\\n<li>查询价格高于所有 SKU 平均价格的 SKU</li>\\n<li>查询下单商品种类最多的前 5 个订单</li>\\n<li>查询 2024 年各个月份的注册用户数</li>\\n<li>查询每个月的订单数量和总金额</li>\\n<li>查询用户名包含\\"hua\\"的用户</li>\\n<li>查询 2025 年下单最多的前 3 位用户</li>\\n</ol>","search_secs":[{"name":"INSERT — 增（插入）","body":"基本语法 示例 假设有学生表： 插入完整数据 插入部分列 省略的列会使用默认值（如果有 DEFAULT）或 NULL： 省略列名 如果提供全部列的值（包括自增列），可以省略列名，但不推荐，可读性差： --- 一次插入多行 --- 查询并插入（INSERT ... SELECT） 将查询结果直接插入到表中： --- RETURNING — 返回插入的数据 PostgreSQL 特有的 RETURNING 子句，可以返回被插入行的数据： 只返回指定列： --- ON CONFLICT — 冲突处理（UPSERT） PostgreSQL 的 INSERT ... ON CONFLICT 可以实现\\"存在则更新，不存在则插入\\"。 EXCLUDED 指代冲突时本次要插入的新值。 不更新，忽略冲突： ---"},{"name":"DELETE — 删（删除）","body":"基本语法 ⚠️ 一定不要忘记写 WHERE！ 不带 WHERE 会清空表。 示例 TRUNCATE 与 DELETE 的区别 RETURNING — 返回被删除的数据 ---"},{"name":"UPDATE — 改（更新）","body":"基本语法 ⚠️ 一定不要忘记写 WHERE！ 不带 WHERE 会更新所有行。 示例 使用其他表的数据更新 RETURNING — 返回更新后的数据 ---"},{"name":"SELECT — 查（查询）","body":"基本语法 查询所有列 表示所有列。开发中建议明确写出列名，避免查询不必要的字段。 查询指定列 列别名 使用 AS 给列起别名（AS 可省略）： --- WHERE — 条件过滤 LIKE 中 % 匹配任意多个字符，_ 匹配单个字符。 --- ORDER BY — 排序 --- LIMIT 和 OFFSET — 分页 OFFSET 从 0 开始计数。第 1 条偏移量为 0。 --- DISTINCT — 去重 --- 聚合函数 --- GROUP BY — 分组 使用 GROUP BY 时，SELECT 中出现的非聚合列必须出现在 GROUP BY 中。 HAVING — 分组后过滤 WHERE 在分组前过滤，HAVING 在分组后过滤： SQL 子句执行顺序： FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT --- "},{"name":"小结","body":"危险操作： 1. 删除所有 DELETE FROM 表名 2. 更新所有 UPDATE语句中没有WHERE"},{"name":"作业","body":"使用 pgAdmin 4 连接 PostgreSQL 16，完成以下练习： 1. 使用电商数据库设计.sql建表（和上节课相同结构） 2. 使用电商数据库示例数据.sql添加示例数据 3. 查询所有商品分类的名称和描述 4. 查询所有用户的用户名、邮箱和注册时间 5. 查询品牌为\\"华为\\"的所有商品 6. 查询价格低于 500 元的 SKU（商品规格） 7. 查询库存大于 300 的 SKU 8. 查询 2024 年注册的用户 9. 查询状态为\\"completed\\"的已完成订单 10. 查询所有不同的商品品牌 11. 查询所有不同的订单状态 12. 查询最贵的 5 个 SKU 13. 查询最新注册的 10 个用户 14. 统计用户总数、商品总数、SKU 总数 15. 计算所有 SKU 的平均价格、最高价和最低价 16. 统计每个分类下有多少个商品 17. 统计每个品牌的商品数量，只显示商品数"}],"progress_key":"db-4"},{"n":5,"slug":"5","title":"事务","group":"课程内容","kicker_mod":"数据库","sec_meta":[{"name":"经典案例 - 银行转账","anchor":"经典案例---银行转账"},{"name":"事务的概念","anchor":"事务的概念"},{"name":"ACID 特性","anchor":"ACID-特性"},{"name":"并行问题","anchor":"并行问题"},{"name":"事务隔离级别","anchor":"事务隔离级别"},{"name":"作业","anchor":"作业"}],"html":"<h1 id=\\"事务\\">事务</h1>\\n<blockquote>\\n<p>pgAdmin4会自动将SQL放到事务中，为了更好的演示：请先讲其设置为不要自动提交</p>\\n</blockquote>\\n<h2 id=\\"经典案例---银行转账\\">经典案例 - 银行转账</h2>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 创建账户表</span>\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">TABLE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">10</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">PRIMARY</span><span class=\\"w\\"> </span><span class=\\"k\\">KEY</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"nb\\">VARCHAR</span><span class=\\"p\\">(</span><span class=\\"mi\\">50</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"nb\\">DECIMAL</span><span class=\\"p\\">(</span><span class=\\"mi\\">12</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">2</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">NOT</span><span class=\\"w\\"> </span><span class=\\"k\\">NULL</span><span class=\\"w\\"> </span><span class=\\"k\\">CHECK</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"p\\">)</span>\\n<span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 插入两个测试账户</span>\\n<span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span>\\n<span class=\\"p\\">(</span><span class=\\"s1\\">\'A\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">500</span><span class=\\"p\\">.</span><span class=\\"mi\\">00</span><span class=\\"p\\">),</span>\\n<span class=\\"p\\">(</span><span class=\\"s1\\">\'B\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'李四\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">1000</span><span class=\\"p\\">.</span><span class=\\"mi\\">00</span><span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 查看初始余额</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 查看总金额（应该始终是 1500.00）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"k\\">SUM</span><span class=\\"p\\">(</span><span class=\\"n\\">balance</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">AS</span><span class=\\"w\\"> </span><span class=\\"n\\">total_balance</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- ============================================</span>\\n<span class=\\"c1\\">-- 模拟转账：从 A 转 100 元给 B</span>\\n<span class=\\"c1\\">-- ============================================</span>\\n\\n<span class=\\"c1\\">-- 步骤1：向 B 加款 100 元</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">+</span><span class=\\"w\\"> </span><span class=\\"mi\\">100</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'B\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 步骤2）：向 A 减款 100 元</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">-</span><span class=\\"w\\"> </span><span class=\\"mi\\">100</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'A\'</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h2 id=\\"事务的概念\\">事务的概念</h2>\\n<p>事务（Transaction）是数据库管理系统中<strong>执行的一组操作</strong>，这组操作要么<strong>全部成功</strong>，要么<strong>全部失败</strong>。</p>\\n<table>\\n<thead>\\n<tr>\\n<th>命令</th>\\n<th>作用</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>BEGIN</code></td>\\n<td>开启一个事务</td>\\n</tr>\\n<tr>\\n<td><code>COMMIT</code></td>\\n<td>提交事务，使所有修改永久生效</td>\\n</tr>\\n<tr>\\n<td><code>ROLLBACK</code></td>\\n<td>回滚事务，撤销所有未提交的修改</td>\\n</tr>\\n<tr>\\n<td><code>SAVEPOINT</code></td>\\n<td>在事务内设置保存点</td>\\n</tr>\\n<tr>\\n<td><code>ROLLBACK TO SAVEPOINT</code></td>\\n<td>回滚到指定保存点，而不影响保存点之前的操作</td>\\n</tr>\\n</tbody>\\n</table>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"k\\">SHOW</span><span class=\\"w\\"> </span><span class=\\"n\\">max_connections</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">pg_backend_pid</span><span class=\\"p\\">();</span>\\n\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"c1\\">-- 步骤1：向 B 加款 100 元</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">+</span><span class=\\"w\\"> </span><span class=\\"mi\\">100</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'B\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 步骤2）：向 A 减款 100 元</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">-</span><span class=\\"w\\"> </span><span class=\\"mi\\">100</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">id</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'A\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"k\\">COMMIT</span><span class=\\"p\\">;</span>\\n<span class=\\"c1\\">-- or</span>\\n<span class=\\"k\\">ROLLBACK</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"ACID-特性\\">ACID 特性</h2>\\n<p>事务有四个核心特性，简称 <strong>ACID</strong>：</p>\\n<table>\\n<thead>\\n<tr>\\n<th>特性</th>\\n<th>全称</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>A</strong></td>\\n<td>Atomicity（原子性）</td>\\n<td>事务中的所有操作要么全部成功，要么全部回滚，不存在部分执行</td>\\n</tr>\\n<tr>\\n<td><strong>C</strong></td>\\n<td>Consistency（一致性）</td>\\n<td>事务执行前后，数据必须满足所有约束和规则</td>\\n</tr>\\n<tr>\\n<td><strong>I</strong></td>\\n<td>Isolation（隔离性）</td>\\n<td>多个事务并发执行时，彼此之间<strong>应该</strong>互不干扰</td>\\n</tr>\\n<tr>\\n<td><strong>D</strong></td>\\n<td>Durability（持久性）</td>\\n<td>事务一旦提交，其结果就是永久的，即使系统崩溃也不会丢失</td>\\n</tr>\\n</tbody>\\n</table>\\n<hr />\\n<h2 id=\\"并行问题\\">并行问题</h2>\\n<p>当多个事务并发执行时，可能出现以下三种问题：</p>\\n<h3 id=\\"脏读Dirty-Read\\">脏读（Dirty Read）</h3>\\n<p>一个事务读到了另一个事务<strong>未提交</strong>的数据。</p>\\n<div class=\\"codehilite\\"><pre><span></span><code>事务A：转账 200（未提交）\\n事务B：读取到余额已减少 200\\n事务A：回滚（余额恢复）\\n事务B：读到了不存在的数据！\\n</code></pre></div>\\n\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 事务 A</span>\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">800</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span>\\n<span class=\\"c1\\">-- 未提交</span>\\n\\n<span class=\\"c1\\">-- 事务 B（如果可以脏读）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- 800（脏数据！）</span>\\n\\n<span class=\\"c1\\">-- 事务 A</span>\\n<span class=\\"k\\">ROLLBACK</span><span class=\\"p\\">;</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- 余额恢复为 1000</span>\\n<span class=\\"c1\\">-- 事务 B 读到的 800 是无效数据</span>\\n</code></pre></div>\\n\\n<blockquote>\\n<p><strong>PostgreSQL 的不会出现脏读。</strong></p>\\n</blockquote>\\n<h3 id=\\"不可重复读Non-repeatable-Read\\">不可重复读（Non-repeatable Read）</h3>\\n<p>同一事务内，两次读取同一数据得到<strong>不同</strong>的结果（因为另一个事务提交了修改）。</p>\\n<div class=\\"codehilite\\"><pre><span></span><code>事务A：第一次查询余额 = 1000\\n事务B：更新余额为 800 并提交\\n事务A：第二次查询余额 = 800（跟上一次不一样！）\\n</code></pre></div>\\n\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 事务 A</span>\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- 1000</span>\\n\\n<span class=\\"c1\\">-- 事务 B（另一个会话）</span>\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">UPDATE</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"mi\\">800</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">COMMIT</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 事务 A（再次查询，结果变了）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">name</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'张三\'</span><span class=\\"p\\">;</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- 800（不可重复读）</span>\\n<span class=\\"k\\">COMMIT</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"幻读Phantom-Read\\">幻读（Phantom Read）</h3>\\n<p>同一事务内，两次查询同一条件的数据集，第二次<strong>多出或少了一行</strong>（另一个事务插入或删除了满足条件的行）。</p>\\n<div class=\\"codehilite\\"><pre><span></span><code>事务A：查询余额 &gt; 500 的用户，得到 2 条\\n事务B：插入一个新用户，余额 600，提交\\n事务A：再次查询余额 &gt; 500 的用户，得到 3 条\\n</code></pre></div>\\n\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 事务 A</span>\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">500</span><span class=\\"p\\">;</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- 2 行</span>\\n\\n<span class=\\"c1\\">-- 事务 B（另一个会话）</span>\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">name</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">VALUES</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"s1\\">\'赵六\'</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">600</span><span class=\\"p\\">);</span>\\n<span class=\\"k\\">COMMIT</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 事务 A（再次查询，多了一行）</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">accounts</span><span class=\\"w\\"> </span><span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">balance</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;</span><span class=\\"w\\"> </span><span class=\\"mi\\">500</span><span class=\\"p\\">;</span><span class=\\"w\\">  </span><span class=\\"c1\\">-- 3 行</span>\\n<span class=\\"k\\">COMMIT</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<h3 id=\\"更新丢失Lost-Update\\">更新丢失（Lost Update）</h3>\\n<p>两个事务同时读取同一数据并修改，后提交的覆盖了先提交的修改。</p>\\n<div class=\\"codehilite\\"><pre><span></span><code>事务A：读取余额 1000，准备扣减 200\\n事务B：读取余额 1000，准备扣减 300\\n事务A：更新余额为 800 并提交\\n事务B：更新余额为 700 并提交（覆盖了事务A的修改！）\\n-- 实际应该：1000 - 200 - 300 = 500\\n-- 结果：700（事务A的扣减丢失了）\\n</code></pre></div>\\n\\n<hr />\\n<h2 id=\\"事务隔离级别\\">事务隔离级别</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>隔离级别</th>\\n<th style=\\"text-align: center;\\">脏读</th>\\n<th style=\\"text-align: center;\\">不可重复读</th>\\n<th style=\\"text-align: center;\\">幻读</th>\\n<th style=\\"text-align: center;\\">更新丢失</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><code>READ COMMITTED</code></td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">可能</td>\\n<td style=\\"text-align: center;\\">可能</td>\\n<td style=\\"text-align: center;\\">可能</td>\\n</tr>\\n<tr>\\n<td><code>REPEATABLE READ</code></td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">可能</td>\\n</tr>\\n<tr>\\n<td><code>SERIALIZABLE</code></td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">❌</td>\\n<td style=\\"text-align: center;\\">❌</td>\\n</tr>\\n</tbody>\\n</table>\\n<blockquote>\\n<p>PostgreSQL 没有实现 <code>READ UNCOMMITTED</code>。如果你设置为 <code>READ UNCOMMITTED</code>，PostgreSQL 会将其当作 <code>READ COMMITTED</code> 处理。</p>\\n</blockquote>\\n<p>隔离级别越高，隔离性越好，性能越低</p>\\n<p>读取或设置隔离级别</p>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- 查看当前隔离级别</span>\\n<span class=\\"k\\">SHOW</span><span class=\\"w\\"> </span><span class=\\"n\\">transaction_isolation</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 在当前事务中设置隔离级别</span>\\n<span class=\\"k\\">BEGIN</span><span class=\\"p\\">;</span>\\n<span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"k\\">TRANSACTION</span><span class=\\"w\\"> </span><span class=\\"k\\">ISOLATION</span><span class=\\"w\\"> </span><span class=\\"k\\">LEVEL</span><span class=\\"w\\"> </span><span class=\\"k\\">READ</span><span class=\\"w\\"> </span><span class=\\"k\\">COMMITTED</span><span class=\\"p\\">;</span>\\n<span class=\\"c1\\">-- ...</span>\\n<span class=\\"k\\">COMMIT</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 也可以在事务开始前设置会话级别</span>\\n<span class=\\"k\\">SET</span><span class=\\"w\\"> </span><span class=\\"n\\">default_transaction_isolation</span><span class=\\"w\\"> </span><span class=\\"o\\">=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'repeatable read\'</span><span class=\\"p\\">;</span>\\n</code></pre></div>\\n\\n<table>\\n<thead>\\n<tr>\\n<th>应用场景</th>\\n<th>推荐隔离级别</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>大多数 Web 应用、报表查询</td>\\n<td><code>READ COMMITTED</code>（默认，够用）</td>\\n</tr>\\n<tr>\\n<td>财务系统、对账（需要同一事务内多次读取一致）</td>\\n<td><code>REPEATABLE READ</code></td>\\n</tr>\\n<tr>\\n<td>极高一致性要求（抢购、库存扣减、防超卖）</td>\\n<td><code>SERIALIZABLE</code></td>\\n</tr>\\n</tbody>\\n</table>\\n<blockquote>\\n<p><strong>大多数情况下，使用默认的 <code>READ COMMITTED</code> 就够了。</strong> 只有在特定需求下才需要提高隔离级别。</p>\\n</blockquote>\\n<hr />\\n<h2 id=\\"作业\\">作业</h2>\\n<p>复述一下问题：</p>\\n<ol>\\n<li>什么时候需要使用事务？</li>\\n<li>如何提交事务？如何回滚事务？</li>\\n<li>什么是ACID？</li>\\n<li>什么是事务隔离级别？</li>\\n</ol>","search_secs":[{"name":"经典案例 - 银行转账","body":""},{"name":"事务的概念","body":"事务（Transaction）是数据库管理系统中执行的一组操作，这组操作要么全部成功，要么全部失败。 ---"},{"name":"ACID 特性","body":"事务有四个核心特性，简称 ACID： ---"},{"name":"并行问题","body":"当多个事务并发执行时，可能出现以下三种问题： 脏读（Dirty Read） 一个事务读到了另一个事务未提交的数据。 PostgreSQL 的不会出现脏读。 不可重复读（Non-repeatable Read） 同一事务内，两次读取同一数据得到不同的结果（因为另一个事务提交了修改）。 幻读（Phantom Read） 同一事务内，两次查询同一条件的数据集，第二次多出或少了一行（另一个事务插入或删除了满足条件的行）。 更新丢失（Lost Update） 两个事务同时读取同一数据并修改，后提交的覆盖了先提交的修改。 ---"},{"name":"事务隔离级别","body":"PostgreSQL 没有实现 READ UNCOMMITTED。如果你设置为 READ UNCOMMITTED，PostgreSQL 会将其当作 READ COMMITTED 处理。 隔离级别越高，隔离性越好，性能越低 读取或设置隔离级别 大多数情况下，使用默认的 READ COMMITTED 就够了。 只有在特定需求下才需要提高隔离级别。 ---"},{"name":"作业","body":"复述一下问题： 1. 什么时候需要使用事务？ 1. 如何提交事务？如何回滚事务？ 1. 什么是ACID？ 1. 什么是事务隔离级别？"}],"progress_key":"db-5"},{"n":6,"slug":"6","title":"索引","group":"课程内容","kicker_mod":"数据库","sec_meta":[],"html":"<h1 id=\\"索引\\">索引</h1>\\n<div class=\\"codehilite lang-sql\\"><pre><span></span><code><span class=\\"c1\\">-- =============================================</span>\\n<span class=\\"c1\\">-- 索引演示：order.created_at</span>\\n<span class=\\"c1\\">-- 演示：无索引 vs 有索引（EXPLAIN ANALYZE）</span>\\n<span class=\\"c1\\">-- =============================================</span>\\n\\n<span class=\\"c1\\">-- 1. 插入 50 万条测试订单（分布在 2 年内）</span>\\n<span class=\\"k\\">INSERT</span><span class=\\"w\\"> </span><span class=\\"k\\">INTO</span><span class=\\"w\\"> </span><span class=\\"ss\\">\\"order\\"</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">user_id</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">order_no</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">status</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">total_amount</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">created_at</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">SELECT</span>\\n<span class=\\"w\\">    </span><span class=\\"p\\">(</span><span class=\\"n\\">random</span><span class=\\"p\\">()</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"mi\\">24</span><span class=\\"w\\"> </span><span class=\\"o\\">+</span><span class=\\"w\\"> </span><span class=\\"mi\\">1</span><span class=\\"p\\">)::</span><span class=\\"nb\\">int</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"s1\\">\'DEMO-\'</span><span class=\\"w\\"> </span><span class=\\"o\\">||</span><span class=\\"w\\"> </span><span class=\\"n\\">LPAD</span><span class=\\"p\\">(</span><span class=\\"k\\">g</span><span class=\\"p\\">::</span><span class=\\"nb\\">text</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">10</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'0\'</span><span class=\\"p\\">),</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">CASE</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"n\\">random</span><span class=\\"p\\">()</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"mi\\">4</span><span class=\\"p\\">)::</span><span class=\\"nb\\">int</span>\\n<span class=\\"w\\">        </span><span class=\\"k\\">WHEN</span><span class=\\"w\\"> </span><span class=\\"mi\\">0</span><span class=\\"w\\"> </span><span class=\\"k\\">THEN</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'pending\'</span>\\n<span class=\\"w\\">        </span><span class=\\"k\\">WHEN</span><span class=\\"w\\"> </span><span class=\\"mi\\">1</span><span class=\\"w\\"> </span><span class=\\"k\\">THEN</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'paid\'</span>\\n<span class=\\"w\\">        </span><span class=\\"k\\">WHEN</span><span class=\\"w\\"> </span><span class=\\"mi\\">2</span><span class=\\"w\\"> </span><span class=\\"k\\">THEN</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'shipped\'</span>\\n<span class=\\"w\\">        </span><span class=\\"k\\">WHEN</span><span class=\\"w\\"> </span><span class=\\"mi\\">3</span><span class=\\"w\\"> </span><span class=\\"k\\">THEN</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'completed\'</span>\\n<span class=\\"w\\">        </span><span class=\\"k\\">ELSE</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'cancelled\'</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">END</span><span class=\\"p\\">,</span>\\n<span class=\\"w\\">    </span><span class=\\"n\\">round</span><span class=\\"p\\">((</span><span class=\\"n\\">random</span><span class=\\"p\\">()</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"mi\\">5000</span><span class=\\"w\\"> </span><span class=\\"o\\">+</span><span class=\\"w\\"> </span><span class=\\"mi\\">50</span><span class=\\"p\\">)::</span><span class=\\"nb\\">numeric</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">2</span><span class=\\"p\\">),</span>\\n<span class=\\"w\\">    </span><span class=\\"k\\">timestamp</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'2024-01-01\'</span><span class=\\"w\\"> </span><span class=\\"o\\">+</span><span class=\\"w\\"> </span><span class=\\"n\\">random</span><span class=\\"p\\">()</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"nb\\">interval</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'2 years\'</span>\\n<span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"n\\">generate_series</span><span class=\\"p\\">(</span><span class=\\"mi\\">1</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"mi\\">500000</span><span class=\\"p\\">)</span><span class=\\"w\\"> </span><span class=\\"k\\">g</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 更新统计信息</span>\\n<span class=\\"k\\">ANALYZE</span><span class=\\"w\\"> </span><span class=\\"ss\\">\\"order\\"</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- ============ 测试 1：无索引 ============</span>\\n<span class=\\"k\\">EXPLAIN</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"k\\">ANALYZE</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">BUFFERS</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"ss\\">\\"order\\"</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">created_at</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'2024-06-01\'</span>\\n<span class=\\"w\\">  </span><span class=\\"k\\">AND</span><span class=\\"w\\"> </span><span class=\\"n\\">created_at</span><span class=\\"w\\"> </span><span class=\\"o\\">&lt;</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'2024-07-01\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- ============ 创建索引 ============</span>\\n<span class=\\"k\\">CREATE</span><span class=\\"w\\"> </span><span class=\\"k\\">INDEX</span><span class=\\"w\\"> </span><span class=\\"n\\">idx_order_created_at</span><span class=\\"w\\"> </span><span class=\\"k\\">ON</span><span class=\\"w\\"> </span><span class=\\"ss\\">\\"order\\"</span><span class=\\"p\\">(</span><span class=\\"n\\">created_at</span><span class=\\"p\\">);</span>\\n\\n<span class=\\"c1\\">-- 更新统计信息（让优化器知道索引存在）</span>\\n<span class=\\"k\\">ANALYZE</span><span class=\\"w\\"> </span><span class=\\"ss\\">\\"order\\"</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- ============ 测试 2：有索引 ============</span>\\n<span class=\\"k\\">EXPLAIN</span><span class=\\"w\\"> </span><span class=\\"p\\">(</span><span class=\\"k\\">ANALYZE</span><span class=\\"p\\">,</span><span class=\\"w\\"> </span><span class=\\"n\\">BUFFERS</span><span class=\\"p\\">)</span>\\n<span class=\\"k\\">SELECT</span><span class=\\"w\\"> </span><span class=\\"o\\">*</span><span class=\\"w\\"> </span><span class=\\"k\\">FROM</span><span class=\\"w\\"> </span><span class=\\"ss\\">\\"order\\"</span>\\n<span class=\\"k\\">WHERE</span><span class=\\"w\\"> </span><span class=\\"n\\">created_at</span><span class=\\"w\\"> </span><span class=\\"o\\">&gt;=</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'2024-06-01\'</span>\\n<span class=\\"w\\">  </span><span class=\\"k\\">AND</span><span class=\\"w\\"> </span><span class=\\"n\\">created_at</span><span class=\\"w\\"> </span><span class=\\"o\\">&lt;</span><span class=\\"w\\"> </span><span class=\\"s1\\">\'2024-07-01\'</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- ============ 清理 ============</span>\\n<span class=\\"k\\">DROP</span><span class=\\"w\\"> </span><span class=\\"k\\">INDEX</span><span class=\\"w\\"> </span><span class=\\"n\\">idx_order_created_at</span><span class=\\"p\\">;</span>\\n\\n<span class=\\"c1\\">-- 可选：删除测试数据（恢复原始 80 条记录）</span>\\n<span class=\\"c1\\">-- DELETE FROM \\"order\\" WHERE order_no LIKE \'DEMO-%\';</span>\\n<span class=\\"c1\\">-- SELECT count(id) FROM \\"order\\";</span>\\n</code></pre></div>","search_secs":[],"progress_key":"db-6"},{"n":7,"slug":"7","title":"拓展知识","group":"课程内容","kicker_mod":"数据库","sec_meta":[{"name":"Postgres的其他能力","anchor":"Postgres的其他能力"},{"name":"数据库的额外知识","anchor":"数据库的额外知识"}],"html":"<h1 id=\\"拓展知识\\">拓展知识</h1>\\n<h2 id=\\"Postgres的其他能力\\">Postgres的其他能力</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>名称</th>\\n<th>它是做什么的</th>\\n<th>什么场景下关注它</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>备份与恢复</strong></td>\\n<td>把数据库的数据倒出来存一份（备份），出问题时能从这份存档把数据还原回去（恢复）</td>\\n<td>上线后必须考虑备份策略</td>\\n</tr>\\n<tr>\\n<td><strong>锁</strong></td>\\n<td>当多个事务同时读写同一条数据时，锁用来决定谁先谁后，防止数据乱掉</td>\\n<td>高并发写入、秒杀、库存扣减等场景，锁是性能瓶颈的根源</td>\\n</tr>\\n<tr>\\n<td><strong>视图</strong></td>\\n<td>把一条 SQL 查询存成一个「虚拟表」，以后可以直接查它，不用每次都写复杂 SQL</td>\\n<td>报表、权限控制、给业务方暴露简化数据接口时</td>\\n</tr>\\n<tr>\\n<td><strong>物化视图</strong></td>\\n<td>和视图类似，但会把查询结果真的存成一张物理表，查起来更快，但数据不是实时最新的</td>\\n<td>大报表、数据仓库、定时刷新的统计看板</td>\\n</tr>\\n<tr>\\n<td><strong>存储过程</strong></td>\\n<td>把多条 SQL 和逻辑写成一个「函数」，存在数据库里，应用端调一次就能跑完所有逻辑</td>\\n<td>业务逻辑全在数据库里跑、批量数据处理、减少应用层网络开销时</td>\\n</tr>\\n<tr>\\n<td><strong>触发器</strong></td>\\n<td>在表上插/改/删数据时，自动执行一段预先写好的逻辑（比如记日志、同步数据）</td>\\n<td>审计日志、数据同步、自动更新某些字段（如 updated_at）</td>\\n</tr>\\n<tr>\\n<td><strong>CTE 表达式</strong></td>\\n<td>写一个临时的命名子查询，让多层嵌套的 SQL 更容易阅读和维护</td>\\n<td>复杂查询拆分、递归查询（树形结构/层级数据）</td>\\n</tr>\\n<tr>\\n<td><strong>全文检索</strong></td>\\n<td>让你在大量文本里按「相关性」快速搜索，支持中文分词、权重、高亮，比 <code>LIKE</code> 高效精准</td>\\n<td>站内搜索、文章/商品搜索，任何需要输入框搜内容的场景</td>\\n</tr>\\n<tr>\\n<td><strong>GIN / GiST 索引</strong></td>\\n<td>特殊索引类型，用来加速全文检索、JSON、数组、空间地理数据等非标类型的查询</td>\\n<td>全文检索、JSON 字段搜索、数组包含查询、地理位置查询</td>\\n</tr>\\n<tr>\\n<td><strong>BRIN 索引</strong></td>\\n<td>一种轻量级索引，按数据在磁盘上的物理块范围建索引，占用空间极小</td>\\n<td>超大表 + 数据天然有序（如时间序列日志），查范围不查单条</td>\\n</tr>\\n<tr>\\n<td><strong>表分区</strong></td>\\n<td>把一张大表从逻辑上拆成多个小表（分区），查询时只扫相关分区，大幅提升性能和管理效率</td>\\n<td>日志表、订单表等随时间增长的超大表，尤其是需要按时间淘汰旧数据</td>\\n</tr>\\n<tr>\\n<td><strong>表继承</strong></td>\\n<td>让一张表从另一张表继承字段，子表可以加自己的字段，查询父表时能查到所有子表数据</td>\\n<td>数据归档、冷热分层（历史数据放子表）、ORM 的多态继承映射</td>\\n</tr>\\n<tr>\\n<td><strong>插件机制</strong></td>\\n<td>PostgreSQL 允许你装各种扩展包来增加功能，比如 <code>postgis</code>（地理信息）、<code>pgvector</code>（向量搜索）</td>\\n<td>当标准功能不够用，需要 GIS、向量检索、定时任务、审计等能力时</td>\\n</tr>\\n<tr>\\n<td><strong>权限系统</strong></td>\\n<td>控制谁能查、谁能改、谁能建表，精确到字段级别</td>\\n<td>多租户、数据安全合规、不同角色分权管理时</td>\\n</tr>\\n<tr>\\n<td><strong>FDW（外部表）</strong></td>\\n<td>在 PostgreSQL 里直接查询另一个数据库（MySQL、Oracle、甚至 CSV 文件）的数据，就像查本地表一样</td>\\n<td>数据迁移、跨库数据整合、临时拉取外部数据做报表</td>\\n</tr>\\n<tr>\\n<td><strong>JSON / JSONB</strong></td>\\n<td>PostgreSQL 原生支持 JSON 数据类型和丰富的 JSON 操作函数，JSONB 是二进制格式，更快且支持索引</td>\\n<td>存半结构化数据（日志、配置、爬虫结果）、灵活 schema、NoSQL 与关系型混合使用</td>\\n</tr>\\n<tr>\\n<td><strong>VACUUM</strong></td>\\n<td>清理旧版本数据、回收磁盘空间、更新统计信息，是保持 PostgreSQL 性能的「保洁工」</td>\\n<td>频繁更新/删除的表性能下降、磁盘空间不释放、查询计划变差时</td>\\n</tr>\\n<tr>\\n<td><strong>复制（流复制 / 逻辑复制）</strong></td>\\n<td>把一台数据库的数据实时同步到另一台或多台，流复制用于高可用，逻辑复制可以按表按行选择性地同步</td>\\n<td>读写分离、异地灾备、跨版本升级、大数据平台实时入仓</td>\\n</tr>\\n</tbody>\\n</table>\\n<h2 id=\\"数据库的额外知识\\">数据库的额外知识</h2>\\n<h3 id=\\"数据库的分类\\">数据库的分类</h3>\\n<table>\\n<thead>\\n<tr>\\n<th>分类</th>\\n<th>数据模型</th>\\n<th>特点</th>\\n<th>代表作</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>关系型数据库</strong></td>\\n<td>表（行+列），SQL 操作</td>\\n<td>严格 Schema、强 ACID、支持 JOIN</td>\\n<td>PostgreSQL、MySQL、Oracle、SQL Server</td>\\n</tr>\\n<tr>\\n<td><strong>文档型数据库</strong></td>\\n<td>JSON/BSON 文档</td>\\n<td>Schema-less、易扩展、适合半结构化数据</td>\\n<td>MongoDB、CouchDB、Firebase Firestore</td>\\n</tr>\\n<tr>\\n<td><strong>键值型数据库</strong></td>\\n<td>Key-Value 对</td>\\n<td>超高读写性能、无查询语言、操作简单</td>\\n<td>Redis、DynamoDB、LevelDB、Riak</td>\\n</tr>\\n<tr>\\n<td><strong>列族型数据库</strong></td>\\n<td>列族，稀疏矩阵存储</td>\\n<td>适合海量写入、列可扩展、压缩率高</td>\\n<td>HBase、Cassandra、Bigtable</td>\\n</tr>\\n<tr>\\n<td><strong>图数据库</strong></td>\\n<td>节点+边，图结构</td>\\n<td>擅长深度关联查询、最短路径/推荐</td>\\n<td>Neo4j、ArangoDB、TigerGraph</td>\\n</tr>\\n</tbody>\\n</table>\\n<blockquote>\\n<p>补充说明：键值型、列族型、图数据库统称为 <strong>NoSQL</strong>；文档型也常归入 NoSQL 阵营。关系型数据库则统称为 <strong>SQL</strong> 数据库。</p>\\n</blockquote>\\n<h3 id=\\"数据库设计三范式\\">数据库设计三范式</h3>\\n<table>\\n<thead>\\n<tr>\\n<th>范式</th>\\n<th>核心要求</th>\\n<th>通俗理解</th>\\n<th>反例</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td><strong>第一范式（1NF）</strong></td>\\n<td>列不可再分，每列都是原子值</td>\\n<td>一个格子只存一个值，不存数组或复合数据</td>\\n<td>一行里存多个联系电话（<code>138xxx, 139xxx</code>）</td>\\n</tr>\\n<tr>\\n<td><strong>第二范式（2NF）</strong></td>\\n<td>满足1NF + 非主键列完全依赖于主键（消除部分依赖）</td>\\n<td>复合主键时，每一列都要依赖整个主键，不能只依赖其中一部分</td>\\n<td><code>订单明细表</code>主键是<code>(订单ID, 商品ID)</code>，但<code>商品名称</code>只依赖<code>商品ID</code></td>\\n</tr>\\n<tr>\\n<td><strong>第三范式（3NF）</strong></td>\\n<td>满足2NF + 非主键列之间不能有传递依赖</td>\\n<td>非主键列不能依赖于另一个非主键列</td>\\n<td><code>学生表</code>有<code>院系ID</code>和<code>院系名称</code>，后者依赖于前者，应拆分出院系表</td>\\n</tr>\\n</tbody>\\n</table>","search_secs":[{"name":"Postgres的其他能力","body":""},{"name":"数据库的额外知识","body":"数据库的分类 补充说明：键值型、列族型、图数据库统称为 NoSQL；文档型也常归入 NoSQL 阵营。关系型数据库则统称为 SQL 数据库。 数据库设计三范式"}],"progress_key":"db-7"}]}]}')}}]);